window.STORY_CATEGORIES = window.STORY_CATEGORIES || {}; window.STORY_CATEGORIES[5] = [{"id":432,"category_id":5,"category_code":"s5","source_id":1,"title":"شاهزاده و زن جادو","content":"پادشاهي پسر جوان و هنرمندي داشت. شبي در خواب ديد كه پسرش مرده است، وحشت‌زده از خواب برخاست، وقتي كه ديد اين حادثه در خواب اتفاق افتاده خيلي خوشحال شد. و آن غم خواب را به شادي بيداري تعبيركرد؛ اما فكر كرد كه اگر روزي پسرش بميرد از او هيچ يادگاري ندارد. پس تصميم گرفت براي پسرش زن بگيرد تا از او نوه‌اي داشته باشد و نسل او باقي بماند. پس از جستجوهاي بسيار، بالاخره پادشاه دختري زيبا را از خانواده‌اي پاك نژاد و پارسا پيدا كرد، اما اين خانوادة پاك نهاد، فقير و تهيدست بودند. زن پادشاه با اين ازدواج مخالفت مي‌كرد. اما شاه با اصرار زياد دختر را به عقد پسرش در آورد. در همين زمان يك زن جادوگر عاشق شاهزاده شد، و حال شاهزاده را چنان تغيير داد كه شاهزاده همسر زيباي خود را رها كرد و عاشق اين زن جادوگر شد. جادو گر پير زن نود ساله‌اي بود مثل ديو سياه و بد بو. شاهزاده به پاي اين گنده پير مي‌افتاد و دست و پاي او را مي‌بوسيد. شاه و درباريان خيلي نارحت بودند. دنيا براي آنها مثل زندان شده بود. شاه از پزشكان زيادي كمك گرفت ولي از كسي كاري ساخته نبود. روز به روز عشق شاهزاده به پيرزن جادو بيشتر مي‌شد، يكسال شاهزاده اسير عشق اين زن بود. شاه يقين كرد كه رازي در اين كار هست. شاه دست دعا به درگاه خدا بلند كرد و از سوز دل دعا كرد. خداوند دعاي او را قبول كرد و ناگهان مرد پارسا و پاكي كه همة اسرار جادو را مي‌دانست، پيش شاه آمد و شاه به او گفت اي مرد بزرگوار به دادم برس. پسرم از دست رفت. مرد ربّاني گفت: نگران نباش، من براي همين كار به اينجا آمده‌ام. هرچه مي‌گويم خوب گوش كن! و مو به مو انجام بده.\r\nفردا سحر به فلان قبرستان برو، در كنار ديوار، رو به قبله، قبر سفيدي هست آن قبر را با بيل و كلنگ باز كن، تا به يك ريسمان برسي. آن ريسمان گرههاي زيادي دارد. گرهها را باز كن و به سرعت از آنجا برگرد.\r\nفردا صبح زود پادشاه طبق دستور همة كارها را انجام داد. به محض اينكه گرهها باز شد شاهزاده به خود آمد و از دام زن جادو نجات يافت. و به كاخ پدرش برگشت. شاه دستور داد چند روز در سراسر كشور جشن گرفتند و شادي كردند. شاهزاده زندگي جديدي را با همسر زيبايش آغاز كرد و زن جادو نيز از غصه، دق كرد و مرد.\r\n"},{"id":433,"category_id":5,"category_code":"s5","source_id":2,"title":"مسجد مهمان كش","content":"در اطراف شهر ري مسجدي بود كه هر كس پاي در آن مي‌گذاشت، كشته مي‌شد. هيچكس جرأت نداشت پا در آن مسجد اسرارآميز بگذارد. مخصوصاً در شب هر كس وارد مي‌شد در همان دم در از ترس مي‌مرد. كم كم آوازة اين مسجد در شهرهاي ديگر پيچيد و به صورت يك راز ترسناك در آمد. تا اينكه شبي مرد مسافر غريبي از راه رسيد و يكسره از مردم سراغ مسجد را گرفت. مردم از كار او حيرت كردند. از او پرسيدند: با مسجد چه كاري داري؟ اين مسجد مهمان‌كش است. مگر نمي‌داني؟ مرد غريب با خونسردي و اطمينان كامل گفت: مي‌دانم، مي‌خواهم امشب در آن مسجد بخوابم. مردم حيرت‌زده گفتند : مگر از جانت سير شده‌اي؟ عقلت كجا رفته؟ مرد مسافر گفت: من اين حرفها سرم نمي‌شود. به اين زندگي دنيا هم دلبسته نيستم تا از مرگ بترسم. مردم بار ديگر او را از اين كار بازداشتند. اما هرچه گفتند، فايده نداشت.\r\nمرد مسافر به حرف مردم توجهي نكرد و شبانه قدم در مسجد اسرارآميز گذاشت و روي زمين دراز كشيد تا بخوابد. در همين لحظه، صداي درشت و هولناكي از سقف مسجد بلند شد و گفت: آهاي كسي كه وارد مسجد شده‌اي! الآن به سراغت مي‌آيم و جانت را مي‌گيرم. اين صداي وحشتناك كه دل را از ترس پاره پاره مي‌كرد پنج بار تكرار شد ولي مرد مسافر غريب هيچ نترسيد و گفت چرا بترسم؟ اين صدا طبل توخالي است. اكنون وقت آن رسيده كه من دلاوري كنم يا پيروز شوم يا جان تسليم كنم. برخاست و بانگ زد كه اگر راست مي‌گويي بيا. من آماده‌ام. ناگهان از شدت صداي وي سقف مسجد فرو ريخت و طلسم آن صدا شكست. از هر گوشه طلا مي‌ريخت. مرد غريب تا بامداد زرها را با توبره از مسجد بيرون مي‌برد و در بيرون شهر درخاك پنهان مي‌كرد و براي آيندگان گنجينه زر مي‌ساخت.\r\n"},{"id":434,"category_id":5,"category_code":"s5","source_id":3,"title":"دوستي موش و قورباغه","content":"موشي و قورباغه‌اي در كنار جوي آبي باهم زندگي مي‌كردند. روزي موش به قورباغه گفت: اي دوست عزيز، دلم مي‌خواهد كه بيشتر از اين با تو همدم باشم و بيشتر با هم صحبت كنيم، ولي حيف كه تو بيشتر زندگي‌ات را توي آب مي‌گذراني و من نمي‌توانم با تو به داخل آب بيايم. قورباغه وقتي اصرار دوست خود را ديد قبول كرد كه نخي پيدا كنند و يك سر نخ را به پاي موش ببندند و سر ديگر را به پاي قورباغه تا وقتي كه بخواهند همديگر را ببينند نخ را بكشند و همديگر را با خبر كنند. روزي موش به كنار جوي آمد تا نخ را بكشد و قورباغه را براي ديدار دعوت كند، ناگهان كلاغي از بالا در يك چشم به هم زدن او را از زمين بلند كرد و به آسمان برد. قورباغه هم با نخي كه به پايش بسته شده بود از آب بيرون كشيده شد و ميان زمين و آسمان آويزان بود. وقتي مردم اين صحنه عجيب را ديدند با تعجب مي‌پرسيدند عجب كلاغ حيله‌گري! چگونه در آب رفته و قورباغه را شكار كرده و با نخ پاي موش را به پاي قورباغه بسته؟!! قورباغه كه ميان آسمان و زمين آويزان بود فرياد مي‌زد اين است سزاي دوستي با مردم نا اهل."},{"id":435,"category_id":5,"category_code":"s5","source_id":4,"title":"صياد سبزپوش","content":"پرنده‌اي گرسنه به مرغزاري رسيد. ديد مقداري دانه بر زمين ريخته و دامي پهن شده و صيادي كنار دام نشسته است. صياد براي اينكه پرندگان را فريب دهد خود را با شاخ و برگ درختها پوشيده بود. پرنده چرخي زد و آمد كنار دام نشست. از صياد پرسيد: اي سبزپوش! تو كيستي كه در ميان اين صحرا تنها نشسته‌اي؟ صياد گفت: من مردي راهب هستم از مردم بريده‌ام و از برگ و ساقة گياهان غذا مي‌خورم. پرنده گفت: در اسلام رهبانيت و جدايي از جامعه حرام است. چگونه تو رهبانيت و دوري از جامعه را انتخاب كرده‌اي؟ از رهبانيت به در آي و با مردم زندگي كن. صياد گفت: اين سخن تو حكم مطلق نيست؟ زيرا اِنزوايِ از مردم هرچه بد باشد از همنشيني با بدان بدتر نيست. سنگ و كلوخ بيابان تنهايند ولي به كسي زياني نمي‌رسانند و فريب هم نمي‌خورند. مردم يكديگر را فريب مي‌دهند. پرنده گفت: تو اشتباه فكر مي‌كني؟ اگر با مردم زندگي كني و بتواني خود را از بدي حفظ كني كار مهمي كرده‌اي و گرنه تنها در بيابان خوب بودن و پاك ماندن كار سختي نيست. صياد گفت: بله، اما چه كسي مي‌تواند بر بديهاي جامعه پيروز شود و فريب نخورد؟ براي اينكه پاك بماني بايد دوست و راهنماي خوبي داشته باشي. آيا در اين زمان چنين كسي پيدا مي‌شود؟ پرنده گفت: بايد قلبت پاك و درست باشد. راهنما لازم نيست. اگر تو درست و صادق باشي، مردم درست و صادق تو را پيدا مي‌كنند. بحث صياد و پرنده بالا گرفت و پرنده چون خيلي گرسنه بود يكسره به دانه‌ها نگاه مي‌كرد. از صياد پرسيد: اين دانه‌ها از توست؟ صياد گفت: نه، از يك كودك يتيم است. آنها را به من سپرده تا نگهداري كنم.حتماً مي‌داني كه خوردن مال يتيم در اسلام حرام است.\r\n پرنده، چون از گرسنگي طاقتش طاق شده بود گفت: من از گرسنگي دارم مي‌ميرم و در حال ناچاري و اضطرار، شريعت اجازه مي‌دهد كه به اندازة رفع گرسنگي از اين دانه‌ها بخورم. صياد گفت: اگر بخوري بايد پول آن را بدهي. صياد پرنده را فريب داد و پرنده كه از گرسنگي صبر و قرار نداشت، قبول كرد كه بخورد و پول دانه‌ها را بدهد. همينكه نزديك دانه‌ها آمد در دام افتاد و آه و ناله‌اش بلند شد.\r\n"},{"id":436,"category_id":5,"category_code":"s5","source_id":5,"title":"شتر گاو و قوچ و يك دسته علف","content":"شتري با گاوي و قوچي در راهي مي‌رفتند. يك دسته علف شيرين و خوشمزه پيش راه آنها پيدا شد. قوچ گفت: اين علف خيلي ناچيز است. اگر آن را بين خود قسمت كنيم هيچ كدام سير نمي‌شويم. بهتر است كه توافق كنيم هركس كه عمر بيشتري دارد او علف را بخورد. زيرا احترام بزرگان واجب است. حالا هركدام تاريخ زندگي خود را مي‌گوييم هركس بزرگتر باشد علف را بخورد. اول قوچ شروع كرد و گفت: من با قوچي كه حضرت ابراهيم بجاي حضرت اسماعيل در مكه قرباني كرد در يك چراگاه بودم. گاو گفت: اما من از تو پيرترم، چون من جفت گاوي هستم كه حضرت آدم زمين را با آنها شخم مي‌زد. شتر كه به دروغهاي شاخدار اين دو دوست خود گوش مي‌داد، بدون سر و صدا سرش را پايين آورد و دستة علف را به دندان گرفت و سرش را بالا برد و در هوا شروع كرد به خوردن. دوستانش اعتراض كردند. او پس از اينكه علف را خورد گفت: من نيازي به گفتن تاريخ زندگي خود ندارم. از پيكر بزرگ و اين گردن دراز من چرا نمي‌فهميد كه من از شما بزرگترم. هر خردمندي اين را مي‌فهمد. اگر شما خردمند باشيد نيازي به ارائة اسناد و مدارك تاريخي نيست."},{"id":437,"category_id":5,"category_code":"s5","source_id":6,"title":"خواب حلوا","content":"روزي يك يهودي با يك نفر مسيحي و يك مسلمان همسفر شدند.در راه به كاروانسرايي رسيدند و شب را در آنجا ماندند. مردي براي ايشان مقداري نان گرم و حلوا آورد. يهودي و مسيحي آن شب غذا زياد خورده بودند ولي مسلمان گرسنه بود. آن دو گفتند ما سير هستيم. امشب صبر مي‌كنيم، غذا را فردا مي‌خوريم. مسلمان گفت: غذا را امشب بخوريم و صبر باشد براي فردا. مسيحي و يهودي گفتند هدف تو از اين فلسفه بافي اين است كه چون ما سيريم تو اين غذا را تنها بخوري. مسلمان گفت: پس بياييد تا آن را تقسيم كنيم هركس سهم خود را بخورد يا نگهدارد. آن دو گفتند اين ملك خداست و ما نبايد ملك خدا را تقسيم كنيم.مسلمان قبول كرد كه شب را صبر كنند و فردا صبح حلوا را بخورند. فردا كه از خواب بيدار شدند گفتند هر كدام خوابي كه ديشب ديده بگويد. هركس خوابش از همه بهتر باشد. اين حلوا را بخورد زيرا او از همه برتر است و جان او از همة جانها كاملتر است.\r\nيهودي گفت: من در خواب ديدم كه حضرت موسي در راه به طرف من آمد و مرا با خود به كوه طور برد. بعد من و موسي و كوه طور تبديل به نور شديم. از اين نور، نوري ديگر روييد و ما هر سه در آن تابش ناپديد شديم. بعد ديدم كه كوه سه پاره شد يك پاره به دريا رفت و تمام دريا را شيرين كرد يك پاره به زمين فرو رفت و چشمه‌اي جوشيد كه همة دردهاي بيماران را درمان مي‌كند. پارة سوم در كنار كعبه افتاد و به كوه مقدس مسلمانان (عرفات) تبديل شد. من به هوش آمدم كوه برجا بود ولي زير پاي موسي مانند يخ آب مي‌شد.\r\nمسيحي گفت: من خواب ديدم كه عيسي آمد و مرا به آسمان چهارم به خانة خورشيد برد. چيزهاي شگفتي ديدم كه در هيچ جاي جهان مانند ندارد. من از يهودي برترم چون خواب من در آسمان اتفاق افتاد و خواب او در زمين. مسلمان گفت: اما اي دوستان پيامبر من آمد و گفت برخيز كه همراه يهودي‌ات با موسي به كوه طور رفته و مسيحي هم با عيسي به آسمان چهارم. آن دو مرد با فضيلت به مقام عالي رسيدند ولي تو ساده دل و كودن در اينجا مانده‌اي. برخيز و حلوا را بخور. من هم ناچار دستور پيامبرم را اطاعت كردم و حلوا را خوردم. آيا شما از امر پيامبر خود سركشي مي‌كنيد؟ آنها گفتند نه در واقع خواب حقيقي را تو ديدة نه ما.\r\n"},{"id":438,"category_id":5,"category_code":"s5","source_id":7,"title":"خياط دزد","content":"قصه‌گويي در شب، نيرنگهاي خياطان را نقل مي‌كرد كه چگونه از پارچه‌هاي مردم مي‌دزدند. عدة زيادي دور او جمع شده بودند و با جان و دل گوش مي‌دادند. نقال از پارچه دزدي بيرحمانة خياطان مي‌گفت. در اين زمان تركي از سرزمين مغولستان از اين سخنان به شدت عصباني شد و به نقال گفت: اي قصه‌گو در شهر شما كدام خياط در حيله‌گري از همه ماهرتر است؟ نقال گفت: در شهر ما خياطي است به نام «پورشش» كه در پارچه دزدي زبانزد همه است. ترك گفت: ولي او نمي‌تواند از من پارچه بدزدد. مردم گفتند : ماهرتر و زيركتر از تو هم فريب او را خورده‌اند. خيلي به عقل خودت مغرور نباش. ترك گفت: نمي‌تواند كلاه سر من بگذارد. حاضران گفتند مي‌تواند. ترك گفت: سر اسب عربي خودم شرط مي‌بندم كه اگر خياط بتواند از پارچة من بدزدد من اين اسب را به شما مي‌دهم ولي اگر نتواند من از شما يك اسب مي‌گيرم. ترك آن شب تا صبح از فكر و خيال خياط دزد خوابش نبرد. فردا صبح زود پارچة اطلسي برداشت و به دكان خياط رفت. با گرمي سلام كرد و استاد خياط با خوشرويي احوال او را پرسيد و چنان با محبت برخورد كرد كه دل ترك را به دست آورد. وقتي ترك بلبل‌زباني خياط را ديد پارچة اطلس استانبولي را پيش خياط گذاشت و گفت از اين پارچه براي من يك لباس جنگ بدوز، بالايش تنگ و پاينش گشاد باشد. خياط گفت: به روي چشم! صدبار ترا با جان و دل خدمت مي‌كنم. آنگاه پارچه را اندازه گرفت، در ضمن كار داستانهايي از اميران و از بخشش‌هاي آنان مي‌گفت. و با مهارت پارچه را قيچي مي‌زد.\r\n ترك از شنيدن داستانها خنده‌اش گرفت و چشم ريز بادامي او از خنده بسته مي‌شد. خياط پاره‌اي از پارچه را دزديد و زير رانش پنهان كرد. ترك از لذت افسانه، ادعاي خود را فراموش كرده بود. از خياط خواست كه باز هم لطيفه بگويد. خياط حيله‌گر لطيفة ديگري گفت و ترك از شدت خنده روي زمين افتاد. خياط تكة ديگري از پارچه را بريد و لاي شلوارش پنهان كرد. ترك براي بار سوم از خياط خواست كه بازهم لطيفه بگويد. باز خياط لطيفة خنده دارتري گفت و ترك را كاملاً شكارخود كرد و باز از پارچه بريد. \r\nبار چهارم ترك تقاضاي لطيفه كرد خياط گفت: بيچاره بس است، اگر يك لطيفة ديگر برايت بگويم قبايت خيلي تنگ مي‌شود. بيشتر از اين بر خود ستم مكن. اگر اندكي از كار من خبر داشتي به جاي خنده، گريه مي‌كردي. هم پارچه‌ات را از دست دادي هم اسبت را در شرط باختي.\r\n"},{"id":439,"category_id":5,"category_code":"s5","source_id":8,"title":"پيرزن و آرايش صورت","content":"پيرزني 90 ساله كه صورتش زرد و مانند سفرة كهنه پر چين و چروك بود. دندانهايش ريخته بود قدش مانند كمان خميده و حواسش از كار افتاده، اما با اين سستي و پيري ميل به شوهر و شهوت در دل داشت. و به شكار شوهر علاقة فراوان داشت. همسايه‌ها او را به عروسي دعوت كردند. پيرزن، جلو آيينه رفت تا صورت خود را آرايش كند، سرخاب بر رويش مي‌‌ماليد اما از بس صورتش چين و چروك داشت، صاف نمي‌شد. براي اينكه چين و چروك ها را صاف كند، نقش‌هاي زيباي وسط آيه‌ها و صفحات قرآن را مي‌بريد و بر صورتش مي‌چسباند و روي آن سرخاب مي‌ماليد. اما همينكه چادر بر سر مي‌گذاشت كه برود نقشها از صورتش باز مي‌شد و مي‌افتاد. باز دوباره آنها را مي‌چسباند. چندين بار چنين كرد و باز تذهيبهاي قرآن از صورتش كنده مي‌شد. ناراحت شد و شيطان را لعنت كرد. ناگهان شيطان در آيينه، پيش روي پيرزن ظاهر شد و گفت: اي فاحشة خشك ناشايست! من كه به حيله‌گري مشهور هستم در تمام عمرم چنين مكري به ذهنم خطور نكرده بود. چرا مرا لعنت مي‌كني تو خودت از صد ابليس مكارتري. تو ورقهاي قرآن را پاره پاره كردي تا صورت زشتت را زيبا كني. اما اين رنگ مصنوعي صورت تو را سرخ و با نشاط نكرد.\r\n*مولوي با استفاده از اين داستان مي‌گويد: اي مردم دغلكار! تا كي سخنان خدا را به دروغ بر خود مي‌بنديد. دل خود را صاف كنيد تا اين سخنان بر دل شما بنشيند و دلهاتان را پر نشاط و زيبا كند.\r\n"},{"id":440,"category_id":5,"category_code":"s5","source_id":9,"title":"عاشق گردو باز","content":"در روزگاران پيش عاشقي بود كه به وفاداري در عشق مشهور بود. مدتها در آرزوي رسيدن به يار گذرانده بود تا اينكه روزي معشوق به او گفت: امشب برايت لوبيا پخته‌ام. آهسته بيا و در فلان اتاق منتطرم بنشين تا بيايم. عاشق خدا را سپاس گفت و به شكر اين خبر خوش به فقيران نان و غذا داد. هنگام شب به آن حجره رفت و به اميد آمدن يار نشست. شب از نيمه گذشت و معشوق آمد. ديد كه جوان خوابش برده. مقداري از آستين جوان را پاره كرد به اين معني كه من به قو‎ْلَم وفا كردم. و چند گردو در جيب او گذاشت به اين معني كه تو هنوز كودك هستي، عاشقي براي تو زود است، هنوز بايد گردو بازي كني. آنگاه يار رفت. سحرگاه كه عاشق از خواب بيدار شد، ديد آستينش پاره است و داخل جيبش چند گردو پيدا كرد. با خود گفت: يار ما يكپارچه صداقت و وفاداري است، هر بلايي كه بر سر ما مي‌آيد از خود ماست."},{"id":441,"category_id":5,"category_code":"s5","source_id":10,"title":"دزد بر سر چاه","content":"شخصي يك قوچ داشت، ريسماني به گردن آن بسته بود و دنبال خود مي‌كشيد. دزدي بر سر راه كمين كرد و در يك لحظه، ريسمان را از دست مرد ربود و گوسفند را دزديد و برد. صاحب قوچ، هاج و واج مانده بود. پس از آن، همه جا دنبال قوچ خود مي‌گشت، تا به سر چاهي رسيد، ديد مردي بر سر چاه نشسته و گريه مي‌كند و فرياد مي‌زند: اي داد! اي فرياد! بيچاره شدم بد بخت شدم. صاحب گوسفند پرسيد: چه شده كه چنين ناله مي‌كني ؟ مرد گفت : يك كيسة طلا داشتم در اين چاه افتاد. اگر بتواني آن را بيرون بياوري، 20% آن را به تو پاداش مي‌دهم. مرد با خود گفت: بيست سكه، قيمت ده قوچ است، اگر دزد قوچم را برد، اما روزي من بيشتر شد. لباسها را از تن در آورد و داخل چاه رفت. مردي كه بر سر چاه بود همان دزدي بود كه قوچ را برده بود. بلافاصله لباسهاي صاحب قوچ را برداشت و برد."},{"id":442,"category_id":5,"category_code":"s5","source_id":11,"title":"خواجة بخشنده و غلام وفادار","content":"درويشي كه بسيار فقير بود و در زمستان لباس و غذا نداشت. هر روز در شهر هرات غلامان حاكم شهر را مي‌ديد كه جامه‌هاي زيبا و گران قيمت بر تن دارند و كمربندهاي ابريشمين بر كمر مي‌بندند. روزي با جسارت رو به آسمان كرد و گفت خدايا! بنده نوازي را از رئيس بخشندة شهر ما ياد بگير. ما هم بندة تو هستيم.\r\nزمان گذشت و روزي شاه خواجه را دستگير كرد و دست و پايش را بست. مي‌خواست بيند طلاها را چه كرده است؟ هرچه از غلامان مي‌پرسيد آنها چيزي نمي‌گفتند. يك ماه غلامان را شكنجه كرد و مي‌گفت بگوييد خزانة طلا و پول حاكم كجاست؟ اگر نگوييد گلويتان را مي‌برم و زبانتان را از گلويتان بيرون مي‌كشم. اما غلامان شب و روز شكنجه را تحمل مي‌كردند و هيچ نمي‌گفتند. شاه آنها را پاره پاره كرد ولي هيچ يك لب به سخن باز نكردند و راز خواجه را فاش نكردند. شبي درويش در خواب صدايي شنيد كه مي‌گفت: اي مرد! بندگي و اطاعت را از اين غلامان ياد بگير.\r\n"},{"id":443,"category_id":5,"category_code":"s5","source_id":12,"title":"دستگيريِ خرها","content":"مردي با ترس و رنگ و رويِ پريده به خانه‌اي پناه برد. صاحبخانه گفت: برادر از چه مي‌ترسي؟ چرا فرار مي‌كني؟ مردِ فراري جواب داد: مأموران بي‌رحم حكومت، خرهاي مردم را به زور مي‌گيرند و مي‌برند. صاحبخانه گفت: خرها را مي‌گيرند ولي تو چرا فرار مي‌كني؟ تو كه خر نيستي؟ مردِ فراري گفت: مأموران احمق‌اند و چنان با جديت خر مي‌گيرند كه ممكن است مرا به جاي خر بگيرند و ببرند."},{"id":444,"category_id":5,"category_code":"s5","source_id":13,"title":"جزيرة سبز و گاو غمگين","content":"جزيرة سرسبز و پر علف است كه در آن گاوي خوش خوراك زندگي مي‌كند. هر روز از صبح تا شب علف صحرا را مي‌خورد و چاق و فربه مي‌شود. هنگام شب كه به استراحت مشغول است يكسره در غم فرداست.آيا فردا چيزي براي خوردن پيدا خواهم كرد؟ او از اين غصه تا صبح رنج مي‌برد و نمي‌خوابد و مثل موي لاغر و باريك مي‌شود. صبح صحرا سبز و خُرِّم است. علفها بلند شده و تا كمر گاو مي‌رسند. دوباره گاو با اشتها به چريدن مشغول مي‌شود و تا شب مي‌چرد و چاق و فربه مي‌شود. باز شبانگاه از ترس اينكه فردا علف براي خوردن پيدا مي‌كند يا نه؟ لاغر و باريك مي‌شود. ساليان سال است كه كار گاو همين است اما او هيچ وقت با خود فكر نكرده كه من سالهاست از اين علف‌‌زار مي‌خورم و علف هميشه هست و تمام نمي‌شود، پس چرا بايد غمناك باشم؟\r\n*تفسير داستان: گاو، رمزِ نفسِ زياده طلبِ انسان است و صحرا هم اين دنياست. آدميزاد، بيقرار و ناآرام و بيمناك است.\r\n"},{"id":445,"category_id":5,"category_code":"s5","source_id":14,"title":"باغ خدا، دست خدا، چوب خدا","content":"مردي در يك باغ درخت خرما را با شدت ‌تكان مي‌داد و بر زمين مي‌ريخت. صاحب باغ آمد و گفت اي مرد احمق! چرا اين كار را مي‌كني؟ دزد گفت: چه اشكالي دارد؟ بندة خدا از باغ خدا خرمايي را بخورد و ببرد كه خدا به او روزي كرده است. چرا بر سفرة گستردة نعمتهاي خداوند حسادت مي‌كني؟ صاحب باغ به غلامش گفت: آهاي غلام! آن طناب را بياور تا جواب اين مردك را بدهم. آنگاه دزد را گرفتند و محكم بر درخت بستند و با چوب بر ساق پا و پشت او مي‌زد. دزد فرياد برآورد، از خدا شرم كن. چرا مي‌زني؟ مرا مي‌كشي. صاحب باغ گفت: اين بندة خدا با چوب خدا در باغ خدا بر پشت خدا مي‌زند. من اراده‌اي ندارم كار، كار خداست. دزد كه به جبر اعتقاد داشت گفت: من اعتقاد به جبر را ترك كردم تو راست مي‌گويي اي مرد بزرگوار نزن. برجهان جبر حاكم نيست بلكه اختيار است اختيار است اختيار."},{"id":446,"category_id":5,"category_code":"s5","source_id":15,"title":"گوشت و گربه","content":"مردي زن فريبكار و حيله‌گري داشت. مرد هرچه مي‌خريد و به خانه مي‌آورد، زن آن را مي‌خورد يا خراب مي‌كرد. مرد كاري نمي‌توانست بكند. روزي مهمان داشتند مرد دو كيلو گوشت خريد و به خانه آورد. زن پنهاني گوشتها را كباب كرد و با شراب خورد. مهمانان آمدند. مرد به زن گفت: گوشتها را كباب كن و براي مهمانها بياور. زن گفت: گربه خورد، گوشتي نيست. برو دوباره بخر. مرد به نوكرش گفت: آهاي غلام! برو ترازو را بياور تا گربه را وزن كنم و ببينم وزنش چقدر است. گربه را كشيد، دو كيلو بود. مرد به زن گفت: خانم محترم! گوشتها دو كيلو بود گربه هم دو كيلو است. اگر اين گربه است پس گوشت ها كو؟ اگر اين گوشت است پس گربه كجاست؟"},{"id":447,"category_id":5,"category_code":"s5","source_id":16,"title":"ليلي و مجنون","content":"مجنون در عشق ليلي مي‌سوخت. دوستان و آشنايان نادان او كه از عشق چيزي نمي‌دانستند گفتند ليلي خيلي زيبا نيست. در شهر ما دختران زيباتر از و زيادند، دختراني مانند ماه، تو چرا اينقدر ناز ليلي را مي‌كشي؟ بيا و از اين دختران زيبا يكي را انتخاب كن. مجنون گفت: صورت و بدن ليلي مانند كوزه است، من از اين كوزه شراب زيبايي مي‌نوشم. خدا از اين صورت به من شراب مست كنندة زيبايي مي‌دهد.شما به ظاهر كوزة دل نگاه مي‌كنيد. كوزه مهم نيست، شراب كوزه مهم است كه مست كننده است. خداوند از كوزة ليلي به شما سركه داد، اما به من شراب داد. شما عاشق نيستيد. خداوند از يك كوزه به يكي زهر مي‌دهد به ديگري شراب و عسل. شما كوزة صورت را مي‌بينيد و آن شراب ناب با چشم ناپاك شما ديده نمي‌شود. مانند دريا كه براي مرغ‌ آبي مثل خانه است اما براي كلاغ باعث مرگ و نابودي است."},{"id":448,"category_id":5,"category_code":"s5","source_id":17,"title":"روز با چراغ گرد شهر","content":"راهبي چراغ به دست داشت و در روز روشن در كوچه ها و خيابانهاي شهر دنبال چيزي مي‌گشت. كسي از او پرسيد: با اين دقت و جديت دنبال چه مي‌گردي، چرا در روز روشن چراغ به دست گرفته‌اي؟\r\nراهب گفت: دنبال آدم مي‌گردم. مرد گفت اين كوچه و بازار پر از آدم است. گفت: بله، ولي من دنبال كسي مي‌گردم كه از روح خدايي زنده باشد. انساني كه در هنگام خشم و حرص و شهوت خود را آرام نگهدارد. من دنبال چنين آدمي مي‌گردم. مرد گفت: دنيال چيزي مي‌گردي كه يافت نمي‌شود.\r\n«ديروز شيخ با چراغ در شهر مي‌گشت و مي‌گفت من از شيطان‌ها وحيوانات خسته شده‌ام آرزوي ديدن انسان دارم. به او گفتند: ما جسته‌ايم يافت نمي‌شود، گفت دنبال همان چيزي كه پيدا نمي‌شود هستم و آرزوي همان را دارم.\r\n"},{"id":449,"category_id":5,"category_code":"s5","source_id":18,"title":"پوستين كهنه در دربار","content":"اياز، غلام شاه محمود غزنوي (پادشاه ايران) در آغاز چوپان بود. وقتي در دربار سلطان محمود به مقام و منصب دولتي رسيد، چارق و پوستين دوران فقر و غلامي خود را به ديوار اتاقش آويزان كرده بود و هر روز صبح اول به آن اتاق مي‌رفت و به آنها نگاه مي‌كرد و از بدبختي و فقر خود ياد مي‌‌آورد و سپس به دربار مي‌رفت. او قفل سنگيني بر در اتاق مي‌بست. درباريان حسود كه به او بدبين بودند خيال كردند كه اياز در اين اتاق گنج و پول پنهان كرده و به هيچ كس نشان نمي‌دهد. به شاه خبر دادند كه اياز طلاهاي دربار را در اتاقي براي خودش جمع و پنهان مي‌كند. سلطان مي‌دانست كه اياز مرد وفادار و درستكاري است. اما گفت: وقتي اياز در اتاقش نباشد برويد و همه طلاها و پولها را براي خود برداريد.\r\nنيمه شب، سي نفر با مشعل‌هاي روشن در دست به اتاق اياز رفتند. با شتاب و حرص قفل را شكستند و وارد اتاق شدند. اما هرچه گشتند چيزي نيافتند. فقط يك جفت چارق كهنه و يك دست لباس پاره آنجا از ديوار آويزان بود. آنها خيلي ترسيدند، چون پيش سلطان دروغزده مي‌شدند.\r\nوقتي پيش شاه آمدند شاه گفت: چرا دست خالي آمديد؟ گنجها كجاست؟ آنها سرهاي خود را پايين انداختند و معذرت خواهي كردند.سلطان گفت: من اياز را خوب مي‌شناسم او مرد راست و درستي است. آن چارق و پوستين كهنه را هر روز نگاه مي‌كند تا به مقام خود مغرور نشود. و گذشته اش را هميشه به ياد بياورد.\r\n"},{"id":450,"category_id":5,"category_code":"s5","source_id":19,"title":"آهو در طويله خران","content":"صيادي، يك آهوي زيبا را شكار كرد واو را به طويلة خران انداخت. در آن طويله، گاو و خر بسيار بود. آهو از ترس و وحشت به اين طرف و آن طرف مي‌گريخت. هنگام شب مرد صياد، كاه خشك جلو خران ريخت تا بخورند. گاوان و خران از شدت گرسنگي كاه را مانند شكر مي‌خوردند. آهو، رم مي‌كرد و از اين سو به آن سو مي‌گريخت، گرد و غبار كاه او را آزار مي‌داد. چندين روز آهوي زيباي خوشبو در طويلة خران شكنجه مي‌شد. مانند ماهي كه از آب بيرون بيفتد و در خشكي در حال جان دادن باشد. روزي يكي از خران با تمسخر به دوستانش گفت: اي دوستان! اين امير وحشي، اخلاق و عادت پادشاهان را دارد، ساكت باشيد. خر ديگري گفت: اين آهو از اين رميدن‌ها و جستن‌ها، گوهري به دست آورده و ارزان نمي‌فروشد. ديگري گفت: اي آهو تو با اين نازكي و ظرافت بايد بروي بر تخت پادشاه بنشيني. خري ديگر كه خيلي كاه خورده بود با اشارة سر، آهو را دعوت به خوردن كرد. آهو گفت كه دوست ندارم. خر گفت: مي‌دانم كه ناز مي‌كني و ننگ داري كه از اين غذا بخوري.\r\nآهو گفت: اي الاغ! اين غذا شايستة توست. من پيش از اين‌كه به اين طويلة تاريك و بد بو بيايم در باغ و صحرا بودم، در كنار آب‌هاي زلال و باغ‌هاي زيبا، اگرچه از بد روزگار در اينجا گرفتار شده‌ام اما اخلاق و خوي پاك من از بين نرفته است. اگر من به ظاهر گدا شوم اما گدا صفت نمي شوم. من لاله سنبل و گل خورده‌ام. خر گفت: هرچه مي‌تواني لاف بزن. در جايي كه تو را نمي‌شناسند مي‌تواني دروغ زياد بگويي. آهو گفت : من لاف نمي‌زنم. بوي زيباي مشك در ناف من گواهي مي‌دهد كه من راست مي‌گويم. اما شما خران نمي‌توانيد اين بوي خوش را بشنويد، چون در اين طويله با بوي بد عادت كرده ايد.\r\n"},{"id":451,"category_id":5,"category_code":"s5","source_id":20,"title":"پر زيبا دشمن طاووس","content":"طاووسي در دشت پرهاي خود را مي‌كند و دور مي‌ريخت. دانشمندي از آنجا مي‌گذشت، از طاووس پرسيد : چرا پرهاي زيبايت را مي‌كني؟ چگونه دلت مي‌آيد كه اين لباس زيبا را بكني و به ميان خاك و گل بيندازي؟ پرهاي تو از بس زيباست مردم براي نشاني در ميان قرآن مي‌گذارند. يا با آن باد بزن درست مي‌كنند. چرا ناشكري مي‌كني؟\r\nطاووس مدتي گريه كرد و سپس به آن دانشمند گفت: تو فريب رنگ و بوي ظاهر را مي‌خوري. آيا نمي‌بيني كه به خاطر همين بال و پر زيبا، چه رنجي مي‌برم؟ هر روز صد بلا و درد از هرطرف به من مي‌رسد. شكارچيان بي رحم براي من همه جا دام مي‌گذارند. تير اندازان براي بال و پر من به سوي من تير مي‌اندازند. من نمي‌توانم با آنها جنگ كنم پس بهتر است كه خود را زشت و بد شكل كنم تا دست از من بر دارند و در كوه و دشت آزاد باشم. اين زيبايي، وسيلة غرور و تكبر است. خودپسندي و غرور بلاهاي بسيار مي‌آورد. پر زيبا دشمن من است. زيبايان نمي‌توانند خود را بپوشانند. زيبايي نور است و پنهان نمي‌ماند. من نمي‌توانم زيبايي خود را پنهان كنم، بهتر است آن را از خود دور كنم.\r\n"},{"id":452,"category_id":5,"category_code":"s5","source_id":21,"title":"اشك رايگان","content":"يك مرد عرب سگي داشت كه در حال مردن بود. او در ميان راه نشسته بود و براي سگ خود گريه مي‌كرد. گدايي از آنجا مي‌گذشت، از مرد عرب پرسيد: چرا گريه مي‌كني؟ عرب گفت: اين سگ وفادار من، پيش چشمم جان مي‌دهد. اين سگ روزها برايم شكار مي‌كرد و شب‌ها نگهبان من بود و دزدان را فراري مي‌داد. گدا پرسيد: بيماري سگ چيست؟ آيا زخم دارد؟ عرب گفت: نه از گرسنگي مي‌ميرد. گدا گفت: صبر كن، خداوند به صابران پاداش مي‌دهد.\r\nگدا يك كيسة پر در دست مرد عرب ديد. پرسيد در اين كيسه چه داري؟ عرب گفت: نان و غذا براي خوردن. گدا گفت: چرا به سگ نمي‌دهي تا از مرگ نجات پيدا كند؟\r\nعرب گفت: نان‌ها را از سگم بيشتر دوست دارم. براي نان و غذا بايد پول بدهم، ولي اشك مفت و مجاني است. براي سگم هر چه بخواهد گريه مي‌كنم. گدا گفت : خاك بر سر تو! اشك خون دل است و به قيمت غم به آب زلال تبديل شده، ارزش اشك از نان بيشتر است. نان از خاك است ولي اشك از خون دل.\r\n"},{"id":453,"category_id":5,"category_code":"s5","source_id":22,"title":"دباغ در بازار عطر فروشان","content":"روزي مردي از بازار عطرفروشان مي‌گذشت، ناگهان بر زمين افتاد و بيهوش شد. مردم دور او جمع شدند و هر كسي چيزي مي‌گفت، همه براي درمان او تلاش مي‌كردند. يكي نبض او را مي‌گرفت، يكي دستش را مي‌ماليد، يكي كاه گِلِ تر جلو بيني او مي‌گرفت، يكي لباس او را در مي‌آورد تا حالش بهتر شود. ديگري گلاب بر صورت آن مرد بيهوش مي‌پاشيد و يكي ديگر عود و عنبر مي‌سوزاند. اما اين درمانها هيچ سودي نداشت. مردم همچنان جمع بودند. هركسي چيزي مي‌گفت. يكي دهانش را بو مي‌كرد تا ببيند آيا او شراب يا بنگ يا حشيش خورده است؟ حال مرد بدتر و بدتر مي‌شد و تا ظهر او بيهوش افتاده بود. همه درمانده بودند. تا اينكه خانواده‌اش باخبر شدند، آن مرد برادر دانا و زيركي داشت او فهميد كه چرا برادرش در بازار عطاران بيهوش شده است، با خود گفت: من درد او را مي‌دانم، برادرم دباغ است و كارش پاك كردن پوست حيوانات از مدفوع و كثافات است. او به بوي بد عادت كرده و لايه‌هاي مغزش پر از بوي سرگين و مدفوع است. كمي سرگين بدبوي سگ برداشت و در آستينش پنهان كرد و با عجله به بازار آمد. مردم را كنار زد، و كنار برادرش نشست و سرش را كنار گوش او آورد بگونه‌اي كه مي‌خواهد رازي با برادرش بگويد. و با زيركي طوري كه مردم نبينند آن مدفوع بد بوي را جلو بيني برادر گرفت. زيرا داروي مغز بدبوي او همين بود. چند لحظه گذشت و مرد دباغ بهوش آمد. مردم تعجب كردند وگفتند اين مرد جادوگر است. در گوش اين مريض افسوني خواند و او را درمان كرد."},{"id":454,"category_id":5,"category_code":"s5","source_id":23,"title":"روي درخت گلابي","content":"زن بدكاري مي‌خواست پيش چشم شوهرش با مرد ديگري هم‌بستر شود. به شوهر خود گفت كه عزيزم من مي‌روم بالاي درخت گلابي و ميوه مي‌چينم. تو ميوه ها را بگير. همين كه زن به بالاي درخت رسيد از آن بالا به شوهرش نگاه ‌كرد و شروع كرد به‌گريستن. شوهر پرسيد: چه شده؟ چرا گريه مي‌كني ؟ زن گفت: اي خود فروش! اي مرد بدكار! اين مرد لوطي كيست كه بر تو افتاده است؟ و تو مانند زنان در زير او خوابيده‌اي؟\r\nشوهر گفت: مگر ديوانه شده‌اي يا سرگيجه داري؟ اينجا غير من هيچكس نيست. زن همچنان حرفش را تكرار مي‌كرد و مي‌گريست. مرد گفت: اي زن تو از بالاي درخت پايين بيا كه دچار سرگيجه شده‌‌اي و عقلت را از دست داده‌اي. زن از درخت پايين آمد و شوهرش بالاي درخت رفت. در اين هنگام زن بلافاصله مرد فاسق را در آغوش كشيد و با او به عشقبازي پرداخت.\r\nشوهرش از بالاي درخت فرياد زد: اي زن بدكاره! آن مرد كيست كه تو را در آغوش گرفته و مانند ميمون روي تو پريده است؟ زن گفت: اينجا غير من هيچ‌كس نيست، حتماً تو هم سر گيجه گرفتة ! حرف مفت مي‌زني. شوهر دوباره نگاه كرد و ديد كه زنش با مردي جمع‌ شده. همچنان حرف‌هايش را تكرار مي‌كرد و به زن پرخاش مي‌كرد. زن مي‌گفت: اين خيالبافي‌ها از اين درخت گلابي است. من هم وقتي بالاي درخت بودم مثل تو همه چيز را غير واقعي مي‌ديدم. زود از درخت پايين بيا تا ببيني كه همه اين خيالبافي‌ها از اين درخت گلابي است.\r\n*سخن مولوي: در هر طنزي دانش و نكتة اخلاقي هست. بايد طنز را با دقت گوش داد. در نظر كساني كه همه چيز را مسخره مي‌كنند هر چيز جدي، هزل است و برعكس در نظر خردمندان همه هزلها جدي است.\r\nدرخت گلابي، در اين داستان رمز وجود مادي انسان است و عالم هوا و هوس و خودخواهي است. در بالاي درخت گلابي فريب مي‌خوري. از اين درخت فرود بيا تا حقيقت را با چشم خود ببيني.\r\n"},{"id":455,"category_id":5,"category_code":"s5","source_id":24,"title":"گوهر پنهان","content":"روزي حضرت موسي به خداوند عرض كرد: اي خداي دانا وتوانا ! حكمت اين كار چيست كه موجودات را مي‌آفريني و باز همه را خراب مي‌كني؟ چرا موجودات نر و مادة زيبا و جذاب مي‌آفريني و بعد همه را نابود مي‌كني؟\r\nخداوند فرمود : اي موسي! من مي‌دانم كه اين سؤال تو از روي ناداني و انكار نيست و گرنه تو را ادب مي‌كردم و به خاطر اين پرسش تو را گوشمالي مي‌دادم. اما مي‌دانم كه تو مي‌خواهي راز و حكمت افعال ما را بداني و از سرّ تداوم آفرينش آگاه شوي. و مردم را از آن آگاه كني. تو پيامبري و جواب اين سؤال را مي‌داني. اين سؤال از علم برمي‌خيزد. هم سؤال از علم بر مي‌خيزد هم جواب. هم گمراهي از علم ناشي مي‌شود هم هدايت و نجات. همچنانكه دوستي و دشمني از آشنايي برمي‌خيزد.\r\nآنگاه خداوند فرمود : اي موسي براي اينكه به جواب سؤالت برسي، بذر گندم در زمين بكار. و صبر كن تا خوشه شود. موسي بذرها را كاشت و گندمهايش رسيد و خوشه شد. داسي برداشت ومشغول درو كردن شد. ندايي از جانب خداوند رسيد كه اي موسي! تو كه كاشتي و پرورش دادي پس چرا خوشه‌ها را مي‌بري؟ موسي جواب داد: پروردگارا ! در اين خوشه‌ها، گندم سودمند و مفيد پنهان است و درست نيست كه دانه‌هاي گندم در ميان كاه بماند، عقل سليم حكم مي‌كند كه گندمها را از كاه بايد جدا كنيم. خداوند فرمود: اين دانش را از چه كسي آموختي كه با آن يك خرمن گندم فراهم كردي؟ موسي گفت: اي خداي بزرگ! تو به من قدرت شناخت و درك عطا فرموده‌اي.\r\nخداوند فرمود : پس چگونه تو قوة شناخت داري و من ندارم؟ در تن خلايق روحهاي پاك هست، روحهاي تيره و سياه هم هست. همانطور كه بايد گندم را از كاه جدا كرد بايد نيكان را از بدان جدا كرد. خلايق جهان را براي آن مي‌آفرينم كه گنج حكمتهاي نهان الهي آشكار شود.\r\n*خداوند گوهر پنهان خود را با آفرينش انسان و جهان آشكار كرد پس اي انسان تو هم گوهر پنهان جان خود را نمايان كن.\r\n"},{"id":456,"category_id":5,"category_code":"s5","source_id":25,"title":"دزد و دستار فقيه","content":"يك عالم دروغين، عمامه‌اش را بزرگ مي‌كرد تا در چشم مردم عوام، او شخص بزرگ و دانايي بنظر بيايد. مقداري پارچه كهنه و پاره، داخل عمامة خود مي‌پيچيد و عمامة بسيار بزرگي درست مي‌كرد و بر سر مي‌گذاشت. ظاهر اين دستار خيلي زيبا و پاك و تميز بود ولي داخل آن پر بود از پارچه كهنه و پاره. يك روز صبح زود او عمامة بزرگ را بر سر گذاشته بود و به مدرسه مي‌رفت. غرور و تكبر زيادي داشت. در تاريكي و گرگ و ميش هواي صبح، دزدي كمين كرده بود تا از رهگذران چيزي بدزدد. دزد چشمش به آن عمامة بزرگ افتاد، با خودش گفت: چه دستار زيبا و بزرگي! اين دستار ارزش زيادي دارد. حمله كرد و دستار را از سر فقيه ربود و پا به فرار گذاشت. آن فقيه‌نما فرياد زد: اي دزد حرامي! اول دستار را باز كن اگر در آن چيز ارزشمندي يافتي آن را ببر. دزد خيال مي‌كرد كه كالاي گران قيمتي را دزديده و با تمام توان فرار مي‌كرد. حس كرد كه چيزهايي از عمامه روي زمين مي‌ريزد، با دقت نگاه كرد، ديد تكه تكه‌هاي پارچه كهنه و پاره پاره‌هاي لباس از آن مي‌ريزد. با عصبانيت آن را بر زمين زد و ديد فقط يك متر پارچة سفيد بيشتر نيست. گفت: اي مرد دغلباز مرا از كار و زندگي انداختي."},{"id":457,"category_id":5,"category_code":"s5","source_id":26,"title":"مرد گِلْ‌خوار","content":"مردي كه به گل خوردن عادت داشت به يك بقالي رفت تا قند سفيد بخرد. بقال مرد دغلكاري بود. به جاي سنگ، گل در ترازو گذاشت تا سبكتر باشد و به مشتري گفت : سنگ ترازوي من از گل است. آيا قبول ميكني؟ مرد گلخوار با خود گفت : چه بهتر!. گل ميوة دل من است. به بقال گفت: مهم نيست، بكش.\r\nبقال گل را در كفّه ترازو گذاشت و شروع كرد به شكستن قند، چون تيشه نداشت و با دست قند را مي‌شكست، به ظاهر كار را طول داد. و پشتش به گلخوار بود، گلخوار ترسان ترسان و تندتند از گل ترازو مي‌خورد و مي‌ترسيد كه بقال او را ببيند، بقال متوجه دزدي گلخوار از گل ترازو شده بود ولي چنان نشان مي‌داد كه نديده است. و با خود مي‌گفت: اي گلخوار بيشتر بدزد، هرچه بيشتر بدزدي به نفع من است. چون تو ظاهراً از گل من مي‌دزدي ولي داري از پهلوي خودت مي‌خوري. تو از فرط خري از من مي‌ترسي، ولي من مي‌ترسم كه توكمتر بخوري. وقتي قند را وزن كنيم مي‌فهمي كه چه كسي احمق و چه كسي عاقل است.مثل مرغي كه به دانه دل خوش مي‌كند ولي همين دانه او را به كام مرگ مي‌كشاند.\r\n"},{"id":458,"category_id":5,"category_code":"s5","source_id":27,"title":"مور و قلم","content":"مورچه‌اي كوچك ديد كه قلمي روي كاغذ حركت مي‌كند و نقش‌هاي زيبا رسم مي‌كند. به مور ديگري گفت اين قلم نقش‌هاي زيبا و عجيبي رسم مي‌كند. نقش‌هايي كه مانند گل ياسمن و سوسن است. آن مور گفت: اين كار قلم نيست، فاعل اصلي انگشتان هستند كه قلم را به نگارش وا مي‌دارند. مور سوم گفت: نه فاعل اصلي انگشت نيست؛ بلكه بازو است. زيرا انگشت از نيروي بازو كمك مي‌گيرد. مورچه‌ها همچنان بحث و گفتگو مي‌كردند و بحث به بالا و بالاتر كشيده شد. هر مورچة نظر عالمانه‌تري مي‌داد تا اينكه مسأله به بزرگ مورچگان رسيد. او بسيار دانا و باهوش بود گفت: اين هنر از عالم مادي صورت و ظاهر نيست. اين كار عقل است. تن مادي انسان با آمدن خواب و مرگ بي هوش و بي‌خبر مي‌شود. تن لباس است. اين نقش‌ها را عقل آن مرد رسم مي‌كند.\r\nمولوي در ادامه داستان مي‌گويد: آن مورچة عاقل هم، حقيقت را نمي‌دانست. عقل بدون خواست خداوند مثل سنگ است. اگر خدا يك لحظه، عقل را به حال خود رها كند همين عقل زيرك بزرگ، ناداني‌ها و خطاهاي دردناكي انجام مي‌دهد.\r\n"},{"id":459,"category_id":5,"category_code":"s5","source_id":28,"title":"پرده نصيحتگو","content":"يك شكارچي، پرنده‌اي را به دام انداخت. پرنده گفت: اي مرد بزرگوار! تو در طول زندگي خود گوشت گاو و گوسفند بسيار خورده‌اي و هيچ وقت سير نشده‌اي. از خوردن بدن كوچك و ريز من هم سير نمي‌شوي. اگر مرا آزاد كني، سه پند ارزشمند به تو مي‌دهم تا به سعادت و خوشبختي برسي. پند اول را در دستان تو مي‌دهم. اگر آزادم كني پند دوم را وقتي كه روي بام خانه‌ات بنشينم به تو مي‌دهم. پند سوم را وقتي كه بر درخت بنشينم. مرد قبول كرد. پرنده گفت:\r\nپند اول اينكه: سخن محال را از كسي باور مكن.\r\nمرد بلافاصله او را آزاد كرد. پرنده بر سر بام نشست.. گفت پند دوم اينكه: هرگز غم گذشته را مخور.برچيزي كه از دست دادي حسرت مخور.\r\nپرنده روي شاخ درخت پريد و گفت : اي بزرگوار! در شكم من يك مرواريد گرانبها به وزن ده درم هست. ولي متأسفانه روزي و قسمت تو و فرزندانت نبود. و گرنه با آن ثروتمند و خوشبخت مي‌شدي. مرد شگارچي از شنيدن اين سخن بسيار ناراحت شد و آه و ناله‌اش بلند شد. پرنده با خنده به او گفت: مگر تو را نصيحت نكردم كه بر گذشته افسوس نخور؟ يا پند مرا نفهميدي يا كر هستي؟پند دوم اين بود كه سخن ناممكن را باور نكني. اي ساده لوح ! همة وزن من سه درم بيشتر نيست، چگونه ممكن است كه يك مرواريد ده درمي در شكم من باشد؟ مرد به خود آمد و گفت اي پرندة دانا پندهاي تو بسيار گرانبهاست. پند سوم را هم به من بگو.\r\nپرنده گفت : آيا به آن دو پند عمل كردي كه پند سوم را هم بگويم.\r\nپند گفتن با نادان خواب‌آلود مانند بذر پاشيدن در زمين شوره‌زار است.\r\n"},{"id":460,"category_id":5,"category_code":"s5","source_id":29,"title":"شاهزاده و زن جادو","content":"پادشاهي پسر جوان و هنرمندي داشت. شبي در خواب ديد كه پسرش مرده است، وحشت‌زده از خواب برخاست، وقتي كه ديد اين حادثه در خواب اتفاق افتاده خيلي خوشحال شد. و آن غم خواب را به شادي بيداري تعبيركرد؛ اما فكر كرد كه اگر روزي پسرش بميرد از او هيچ يادگاري ندارد. پس تصميم گرفت براي پسرش زن بگيرد تا از او نوه‌اي داشته باشد و نسل او باقي بماند. پس از جستجوهاي بسيار، بالاخره پادشاه دختري زيبا را از خانواده‌اي پاك نژاد و پارسا پيدا كرد، اما اين خانوادة پاك نهاد، فقير و تهيدست بودند. زن پادشاه با اين ازدواج مخالفت مي‌كرد. اما شاه با اصرار زياد دختر را به عقد پسرش در آورد. در همين زمان يك زن جادوگر عاشق شاهزاده شد، و حال شاهزاده را چنان تغيير داد كه شاهزاده همسر زيباي خود را رها كرد و عاشق اين زن جادوگر شد. جادو گر پير زن نود ساله‌اي بود مثل ديو سياه و بد بو. شاهزاده به پاي اين گنده پير مي‌افتاد و دست و پاي او را مي‌بوسيد. شاه و درباريان خيلي نارحت بودند. دنيا براي آنها مثل زندان شده بود. شاه از پزشكان زيادي كمك گرفت ولي از كسي كاري ساخته نبود. روز به روز عشق شاهزاده به پيرزن جادو بيشتر مي‌شد، يكسال شاهزاده اسير عشق اين زن بود. شاه يقين كرد كه رازي در اين كار هست. شاه دست دعا به درگاه خدا بلند كرد و از سوز دل دعا كرد. خداوند دعاي او را قبول كرد و ناگهان مرد پارسا و پاكي كه همة اسرار جادو را مي‌دانست، پيش شاه آمد و شاه به او گفت اي مرد بزرگوار به دادم برس. پسرم از دست رفت. مرد ربّاني گفت: نگران نباش، من براي همين كار به اينجا آمده‌ام. هرچه مي‌گويم خوب گوش كن! و مو به مو انجام بده.\r\nفردا سحر به فلان قبرستان برو، در كنار ديوار، رو به قبله، قبر سفيدي هست آن قبر را با بيل و كلنگ باز كن، تا به يك ريسمان برسي. آن ريسمان گرههاي زيادي دارد. گرهها را باز كن و به سرعت از آنجا برگرد.\r\nفردا صبح زود پادشاه طبق دستور همة كارها را انجام داد. به محض اينكه گرهها باز شد شاهزاده به خود آمد و از دام زن جادو نجات يافت. و به كاخ پدرش برگشت. شاه دستور داد چند روز در سراسر كشور جشن گرفتند و شادي كردند. شاهزاده زندگي جديدي را با همسر زيبايش آغاز كرد و زن جادو نيز از غصه، دق كرد و مرد.\r\n"},{"id":461,"category_id":5,"category_code":"s5","source_id":30,"title":"تشنه صداي آب","content":"آب در گودالي عميق در جريان بود و مردي تشنه از درخت گردو بالا رفت و درخت را تكان مي‌داد. گردوها در آب مي‌افتاد و همراه صداي زيباي آب حبابهايي روي آب پديد مي‌آمد، مرد تشنه از شنيدن صدا و ديدن حباب لذت مي‌‌برد. مردي كه خود را عاقل مي‌پنداشت از آنجا مي‌گذشت به مرد تشنه گفت : چه كار مي‌كني؟\r\nمرد گفت: تشنة صداي آبم.\r\nعاقل گفت: گردو گرم است و عطش مي‌آورد. در ثاني، گردوها درگودال آب مي‌ريزد و تو دستت به گردوها نمي‌رسد. تا تو از درخت پايين بيايي آب گردوها را مي‌برد.\r\nتشنه گفت: من نمي‌خواهم گردو جمع كنم. من از صداي آب و زيبايي حباب لذت مي‌برم. مرد تشنه در اين جهان چه كاري دارد؟ جز اينكه دائم دور حوض آب بچرخد، مانند حاجيان كه در مكه دور كعبه مي‌گردند.\r\nشرح داستان: اين داستان سمبوليك است. آب رمز عالم الهي و صداي آب رمز الحان موسيقي است. مرد تشنه، رمز عارف است كه از بالاي درخت آگاهي به جهان نگاه مي‌كند. و در اشياء لذت مادي نمي‌بيند.بلكه از همه چيز صداي خدا را مي‌شنود. مولوي تشنگي و طلب را بزرگترين عامل براي رسيدن به حقيقت مي‌داند.\r\n"},{"id":462,"category_id":5,"category_code":"s5","source_id":31,"title":"زن بد كار و كفشدوز","content":"روزي يك صوفي ناگهاني و بدون در زدن وارد خانه شد و ديد كه زنش با مرد كفشدوز در اتاقي دربسته تنهايند و با هم جفت شده‌اند. معمولا صوفي در آن ساعت از مغازه به خانه نمي‌آمد و زن بارها در غياب شوهرش اين‌كار را كرده بود و اتفاقي نيفتاده بود. ولي صوفي آن روز بي‌وقت به خانه آمد. زن و مرد كفشدوز بسيار ترسيدند. زن در خانه هيچ جايي براي پنهان كردن مرد پيدا نكرد، زود چادر خود را بر سر مرد بيگانه انداخت و او را به شكل زنان درآورد و در اتاق را باز كرد. صوفي تمام اين ماجرا را از پشت پنجره ديده بود، خود را به ناداني زد و با خود گفت: اي بي‌دينها! از شما كينه مي‌كشم ولي به آرامي و با صبر. صوفي سلام كرد و از زنش پرسيد: اين خانم كيست؟ زنش گفت: ايشان يكي از زنان اشراف و ثروتمند شهر هستند، من در خانه را بستم تا بيگانه‌اي ناآگاهانه وارد خانه نشود. صوفي گفت : ايشان از ما چه خدمتي مي‌خواهند، تا با جان و دل انجام دهم؟ زن گفت: اين خانم تمايل دارد با ما قوم و خويش شود. ايشان پسري بسيار زيبا و باهوش دارد و آمده تا دختر ما را ببيند و براي پسرش خواستگاري كند، اما دختر به مكتبخانه رفته است. صوفي گفت: ما فقير و بينوا هستيم و همشأن اين خانوادة بزرگ و ثروتمند نيستيم، چگونه مي‌توانيم با ايشان وصلت كنيم. در ازدواج بايد دو خانواده با هم برابر باشند. زن گفت: درست مي‌گويي من نيز همين را به خانم گفتم و گفتم كه ما فقير و بينوا هستيم؛ اما او مي‌گويد كه براي ما اين مسأله مهم نيست ما دنبال مال وثروت نيستيم. بلكه دنبال پاكي و نيكي هستيم. صوفي دوباره حرفهاي خود را تكرار كرد و از فقيري خانوادة خود گفت. زن صوفي خيال مي‌كرد كه شوهرش فريب او را خورده است، با اطمينان به شوهرش گفت: شوهر عزيزم! من چند بار اين مطلب را گفته‌ام و گفته‌ام كه دختر ما هيچ جهيزيه‌اي ندارد ولي ايشان با قاطعيت مي‌گويد پول و ثروت بي ارزش است، من در شما تقوي و پاكي و راستي مي‌بينم.\r\nصوفي، رندانه در سخني دو پهلو گفت: بله ايشان از همة چيز زندگي ما باخبرند و هيچ چيز ما بر ايشان پوشيده نيست. مال و اسباب ما را مي‌بيند و مي‌بيند خانة ما آنقدر تنگ است كه هيچ چيز در آن پنهان نمي‌‌ماند. همچنين ايشان پاكي و تقوي و راستي ما را از ما بهتر مي‌داند. پيدا و پنهان و پس و پيش ما را خوب مي‌شناسد. حتماً او از پاكي و راستي دختر ما هم خوب آگاه است. وقتي كه همه چيز ما براي ايشان روشن است، درست نيست كه من از پاكي وراستي دخترم بگويم و از دختر خود تعريف ‌كنم!!\r\n"},{"id":463,"category_id":5,"category_code":"s5","source_id":32,"title":"خرگوش پيامبر ماه","content":"گله‌اي از فيلان گاه گاه بر سر چشمة زلالي جمع مي‌شدند و آنجا مي‌خوابيدند. حيوانات ديگر از ترس فرار مي‌كردند و مدتها تشنه مي‌ماندند. روزي خرگوش زيركي چاره انديشي كرد و حيله‌ا‌ي بكار بست. برخاست و پيش فيلها رفت. فرياد كشيد كه : اي شاه فيلان ! من فرستاده و پيامبر ماه تابانم. ماه به شما پيغام داد كه اين چشمه مال من است و شما حق نداريد بر سر چشمه جمع شويد. اگر از اين ببعد كنار چشمه جمع شويد شما را به مجازات سختي گرفتار خواهم كرد. نشان راستي گفتارم اين است كه اگر خرطوم خود را در آب چشمه بزنيد ماه آشفته خواهد شد. و بدانيد كه اين نشانه درست در شب چهاردهم ماه پديدار خواهد شد.\r\nپادشاه فيلان در شب چهاردهم ماه با گروه زيادي از فيلان بر سر چشمه حاضر شدند تا ببينند حرف خرگوش درست است يا نه؟ همين كه پادشاه خرطوم خود را به آب زد تصوير ماه در آب به لرزش در آمد و آشفته شد. شاه پيلان فهميد كه حرفهاي خرگوش درست است. از ترس پا پس كشيد و بقية فيلها به دنبال او از چشمه دور شدند.\r\n"},{"id":464,"category_id":5,"category_code":"s5","source_id":33,"title":"درويش يكدست","content":"درويشي در كوهساري دور از مردم زندگي مي‌كرد و در آن خلوت به ذكر خدا و نيايش مشغول بود. در آن كوهستان، درختان سيب و گلابي و انار بسيار بود و درويش فقط ميوه مي‌خورد. روزي با خدا عهد كرد كه هرگز از درخت ميوه نچيند و فقط از ميوه‌هايي بخورد كه باد از درخت بر زمين مي‌ريزد. درويش مدتي به پيمان خود وفادار بود، تا اينكه امر الهي، امتحان سختي براي او پيش ‌آورد. تا پنج روز، هيچ ميوه‌اي از درخت نيفتاد. درويش بسيار گرسنه و ناتوان شد، و بالاخره گرسنگي بر او غالب شد. عهد و پيمان خود را شكست و از درخت گلابي چيد و خورد. خداوند به سزاي اين پيمان شكني او را به بلاي سختي گرفتار كرد.\r\nقصه از اين قرار بود كه روزي حدود بيست نفر دزد به كوهستان نزديك درويش آمده بودند و اموال دزدي را ميان خود تقسيم مي‌كردند. يكي از جاسوسان حكومت آنها را ديد و به داروغه خبر داد. ناگهان مأموران دولتي رسيدند و دزدان را دستگير كردند و درويش را هم جزو دزدان پنداشتند و او را دستگير كردند. بلافاصله، دادگاه تشكيل شد و طبق حكم دادگاه يك دست و يك پاي دزدان را قطع كردند. وقتي نوبت به درويش رسيد ابتدا دست او را قطع كردند و همينكه خواستند پايش را ببرند، يكي از مأموران بلند مرتبه از راه رسيد و درويش را شناخت و بر سر مأمور اجراي حكم فرياد زد و گفت: اي سگ صفت! اين مرد از درويشان حق است چرا دستش را بريدي؟\r\nخبر به داروغه رسيد، پا برهنه پيش شيخ آمد و گريه كرد و از او پوزش و معذرت بسيار خواست.اما درويش با خوشرويي و مهرباني گفت : اين سزاي پيمان شكني من بود من حرمت ايمان به خدا را شكستم و خدا مرا مجازات كرد.\r\nاز آن پس در ميان مردم با لقب درويش دست بريده معروف بود. او همچنان در خلوت و تنهايي و به دور از غوغاي خلق در كلبه‌اي بيرون شهر به عبادت و راز و نياز با خدا مشغول بود. روزي يكي از آشنايان سر زده، نزد او آمد و ديد كه درويش با دو دست زنبيل مي‌بافد. درويش ناراحت شد و به دوست خود گفت چرا بي خبر پيش من آمدي؟ مرد گفت: از شدت مهر و اشتياق تاب دوري شما را نداشتم. شيخ تبسم كرد و گفت: ترا به خدا سوگند مي‌‌دهم تا زمان مرگ من، اين راز را با هيچكس نگويي.\r\nاما رفته رفته راز كرامت درويش فاش شد و همة مردم از اين راز با خبر شدند. روزي درويش در خلوت با خدا گفت: خدايا چرا راز كرامت مرا بر خلق فاش كردي؟ خداوند فرمود: زيرا مردم نسبت به تو گمان بد داشتند و مي‌گفتند او رياكار و دزد بود و خدا او را رسوا كرد. راز كرامت تو را بر آنان فاش كردم تا بدگماني آنها بر طرف شود و به مقام والاي تو پي ببرند.\r\n"},{"id":465,"category_id":5,"category_code":"s5","source_id":34,"title":"خواندن نامة عاشقانه در نزد معشوق","content":"معشوقي، عاشق خود را به خانه دعوت كرد و كنار خود نشاند. عاشق بلافاصله تعداد زيادي نامه كه قبلاً در زمان دوري و جدايي براي يارش نوشته بود، از جيب خود بيرون آورد و شروع به خواندن كرد. نامه‌ها پر از آه و ناله و سوز و گداز بود، خلاصه آنقدر خواند تا حوصلة معشوق را سر برد. معشوق با نگاهي پر از تمسخر و تحقير به او گفت: اين نامه‌ها را براي چه كسي نوشته‌اي؟ عاشق گفت: براي تو اي نازنين! معشوق گفت: من كه كنار تو نشسته‌ام و آماده‌ام تو مي‌تواني از كنار من لذت ببري. اين كار تو در اين لحظه فقط تباه كردن عمر و از دست دادن وقت است.\r\nعاشق جواب داد: بله، مي‌دانم من الآن در كنار تو نشسته‌ام اما نمي‌دانم چرا آن لذتي كه از ياد تو در دوري و جدايي احساس مي‌كردم اكنون كه در كنار تو هستم چنان احساسي ندارم؟ معشوق مي‌گويد: علتش اين است كه تو، عاشق حالات خودت هستي نه عاشق من. براي تو من مثل خانة معشوق هستم نه خود معشوق. تو بستة حال هستي. و ازين رو تعادل نداري. مرد حق بيرون از حال و زمان مي‌نشيند. او امير حالها ست و تو اسير حالهاي خودي. برو و عشق مردان حق را بياموز و گرنه اسير و بندة حالات گوناگون خواهي بود. به زيبايي و زشتي خود نگاه مكن بلكه به عشق و معشوق خود نگاه كن. در ضعف و قدرت خود نگاه مكن، به همت والاي خود نگاه كن و در هر حالي به جستجو و طلب مشغول باش.\r\n"},{"id":466,"category_id":5,"category_code":"s5","source_id":35,"title":"استر و اشتر","content":"استري و شتري با هم دوست بودند، روزي استر به شتر گفت: اي رفيق! من در هر فراز و نشيبي و يا در راه هموار و در راه خشك يا تر هميشه به زمين مي‌افتم ولي تو به راحتي مي‌روي و به زمين نمي‌خوري. علت اين امر چيست؟ بگو چه بايد كرد. درست راه رفتن را به من هم ياد بده.\r\nشتر گفت: دو علت در اين كار هست: اول اينكه چشم من از چشم تو دوربين‌تر است و دوم اينكه من قدّم بلندتر است و از بلندي نگاه مي‌كنم، وقتي بر سر كوه بلند مي‌رسم از بلندي همة راه‌ها و گردنه‌ها را با هوشمندي مي‌نگرم. من ازسر بينش گام بر مي‌دارم و به همين دليل نمي‌افتم و براحتي راه را طي مي‌كنم. تو فقط تا دو سه قدم پيش پاي خود را مي‌بيني و در راه دوربين و دور انديش نيستي.\r\n"},{"id":467,"category_id":5,"category_code":"s5","source_id":36,"title":"رقص صوفي بر سفرة خالي","content":"يك صوفي, سفره‌اي ديد كه خالي است و از درخت آويزان است. صوفي شروع به رقص كرد و از عشق نان و غذاي سفره شادي مي‌كرد و جامه خود را مي‌دريد و شعر مي‌خواند: «نانِ بي‌نان, سفره درد گرسنگي و قحطي را درمان مي‌كند». شور و شادي او زياد شد. صوفيان ديگر هم با او به رقص درآمدند هوهو مي‌زدند و از شدت شور و شادي چند نفر مست و بيهوش افتادند. مردي پرسيد. اين چه كار است كه شما مي‌كنيد؟ رقص و شادي براي سفره بي‌نان و غذا چه معني دارد؟ صوفي گفت: مرد حق در فكر «هستي» نيست. عاشقانِ حق با بود و نبود كاري ندارند. آنان بي سرمايه, سود مي‌برند. آنها , «عشق به نان» را دوست دارند نه نان را. آنها مرداني هستند كه بي‌بال دور جهان پرواز مي‌كنند. عاشقان در عدم ساكن‌اند. و مانند عدم يك رنگ هستند و جانِ واحد دارند."},{"id":468,"category_id":5,"category_code":"s5","source_id":37,"title":"دزد دهل زن","content":"دزدي در نيمه شب, پاي ديواري را با كلنگ مي‌كَنَد. تا سوراخ كُنَد و وارد خانه شود. مردي كه نيمه شب بيمار بود و خوابش نمي برد صداي تق تق كلنگ را مي‌شنيد. بالاي بام رفت و به پايين نگاه كرد. دزدي را ديد كه ديوار را سوراخ مي‌كند. گفت: اي مرد تو كيستي؟ دزد گفت من دُهُل زن هستم. گفت چه كار مي‌كني در اين نيمه شب؟\r\nدزد گفت: دُهُل مي‌زنم. مرد گفت: پس كو صداي دُهُل ؟ دزد گفت: فردا صداي آن را مي‌شنوي. فردا از گلوي صاحبخانه صداي دُهُل من بيرون مي‌آيد.\r\n"},{"id":469,"category_id":5,"category_code":"s5","source_id":38,"title":"دقوقي","content":"دقوقي يك درويش بسيار بزرگ و با كمال بود. و بيشتر عمر خود را در سير وسفر مي‌گذراند.و بندرت دو روز در يكجا توقف مي‌كرد. بسيار پاك و ديندار و با تقوي بود. انديشه‌ها و نظراتش درست و دقيق بود. اما با اينهمه بزرگي و كمال، پيوسته در جست وجوي اولياي يگانة خدا بود و يك لحظه از جست و جو باز نمي‌ايستاد. سالها بدنبال انسان كامل مي‌گشت. پابرهنه و جامه چاك، بيابانها ي پر خار و كوههاي پر از سنگ را طي مي‌كرد و از اشتياق او ذرة كم نمي‌شد.\r\nسرانجام پس از سالها سختي و رنج، به ساحل دريايي رسيد و با منظرة عجيبي روبرو شد. او داستان را چنين تعريف مي‌كند:\r\n ناگهان از دور در كنار ساحل هفت شمع بسيار روشن ديدم،كه شعلة آنها تا اوج آسمان بالا مي‌رفت. با خودم گفتم: اين شمعها ديگر چيست؟ اين نور از كجاست؟چرا مردم اين نور عحيب را نمي‌بينند؟درهمين حال ناگهان آن هفت شمع به يك شمع تبديل شدند و نور آن هفت برابر شد. دوباره آن شمع، هفت شمع شد و ناگهان هفت شمع به شكل هفت مرد نوراني درآمد كه نورشان به اوج آسمان مي‌رسيد. حيرتم زياد و زيادتر شد. كمي جلوتر رفتم و با دقت نگاه كردم. منظرة عجيب‌تري ديدم. ديدم كه هر كدام از آن هفت مرد به صورت يك درخت بزرگ با برگهاي درشت و پراز ميوه‌هاي شاداب و شيرين پيش روي من ايستاده‌اند. از خودم پرسيدم: چرا هر روز هزاران نفر از مردم از كنار اين درختان مي‌گذرند ولي آنها را نمي‌بينند؟ باز هم جلوتر رفتم، ديدم هفت درخت يكي شدند. باز ديدم كه هفت درخت پشت سر اين درخت به صف ايستاده‌اند.گويي نماز جماعت مي‌خوانند. خيلي عجيب بود درختها مثل انسانها نماز مي‌خواندند، مي‌ايستادند، در برابر خدا خم و راست مي‌شدند و پيشاني بر خاك مي‌گذاشتند. سپس آن هفت درخت، هفت مرد شدند و دور هم جمع شدند و انجمن تشكيل دادند. از حيرت درمانده بودم. چشمانم را مي‌ماليدم، با دقت نگاه كردم تا ببينم آن ها چه كساني هستند؟ نزديكتر رفتم و سلام كردم. جواب سلام مرا دادند و مرا با اسم صدا زدند. مبهوت شدم. آنها نام مرا از كجا مي‌دانند؟ چگونه مرا مي‌شناسند؟ من در اين فكر بودم كه آنها فكر و ذهن مرا خواندند. و پيش از آنكه بپرسم گفتند: چرا تعجب كرده‌اي مگر نمي‌داني كه عارفان روشن‌ بين از دل و ضمير ديگران باخبرند و اسرار و رمزهاي جهان را مي‌دانند؟ آنگه به من گفتند : ما دوست داريم با تو نماز جماعت بخوانيم و تو امام نماز ما باشي. من قبول كردم.\r\nنماز جماعت در ساحل دريا آغاز شد، در ميان نماز چشم دقوقي به موجهاي متلاطم دريا افتاد. ديد در ميانة امواج بزرگ يك كشتي گرفتار شده و توفان، موجهاي كوه‌پيكر را برآن مي‌كوبد و باد صداي شوم مرگ و نابودي را مي‌آورد. مسافران كشتي از ترس فرياد مي‌كشيدند. قيامتي بر پا شده بود. دقوقي كه در ميان نماز اين ماجرا را مي‌ديد، دلش به رحم‌آمد و از صميم دل براي نجات مسافران دعا كرد. و با زاري و ناله از خدا خواست كه آنها را نجات دهد.خدا دعاي دقوقي را قبول كرد و آن كشتي به سلامت به ساحل رسيد. نماز مردان نوراني نيز به پايان رسيد. در اين حال آن هفت مرد نوراني آهسته از هم مي‌پرسيدند: چه كسي در كار خدا دخالت كرد و سرنوشت را تغيير داد؟ هر كدام گفتند: من براي مسافران دعا نكردم. يكي از آنان گفت: دقوقي از سر درد براي مسافران كشتي دعا كرد و خدا هم دعاي او را اجابت كرد.\r\nدقوقي مي‌گويد:« من جلو آنها نشسته بودم سرم را برگرداندم تا ببينم آنها چه مي‌گويند. اما هيچكس پشت سرم نبود. همه به آسمان رفته بودند. اكنون سالهاست كه من در آرزوي ديدن آنها هستم ولي هنوز نشاني از آنها نيافته‌ام.\"\r\n"},{"id":470,"category_id":5,"category_code":"s5","source_id":39,"title":"معلم و كودكان","content":"كودكان مكتب از درس و مشق خسته شده بودند. با هم مشورت كردند كه چگونه درس را تعطيل كنند و چند روزي از درس و كلاس راحت باشند. يكي از شاگردان كه از همه زيركتر بود گفت: فردا ما همه به نوبت به مكتب مي‌آييم و يكي يكي به استاد مي‌گوييم چرا رنگ و رويتان زرد است؟ مريض هستيد؟ وقتي همه اين حرف را بگوييم او باور مي‌كند و خيال بيماري در او زياد مي‌شود. همة شاگردان حرف اين كودك زيرك را پذيرفتند و با هم پيمان بستند كه همه در اين كار متفق باشند، و كسي خبرچيني نكند.\r\nفردا صبح كودكان با اين قرار به مكتب آمدند. در مكتب‌خانه كلاس درس در خانة استاد تشكيل مي‌شد. همه دم در منتظر شاگرد زيرك ايستادند تا اول او داخل برود و كار را آغاز كند.او آمد و وارد شد و به استاد سلام كرد و گفت : خدا بد ندهد؟ چرا رنگ رويتان زرد است؟\r\nاستاد گفت: نه حالم خوب است و مشكلي ندارم، برو بنشين درست را بخوان.اما گمان بد در دل استاد افتاد. شاگرد دوم آمد و به استاد گفت : چرا رنگتان زرد است؟ وهم در دل استاد بيشتر شد. همينطور سي شاگرد آمدند و همه همين حرف را زدند. استاد كم كم يقين كرد كه حالش خوب نيست. پاهايش سست شد به خانه آمد، شاگردان هم به دنبال او آمدند. زنش گفت چرا زود برگشتي؟ چه خبر شده؟ استاد با عصبانيت به همسرش گفت: مگر كوري؟ رنگ زرد مرا نمي‌بيني؟ بيگانه‌ها نگران من هستند و تو از دورويي و كينه، بدي حال مرا نمي‌بيني. تو مرا دوست نداري. چرا به من نگفتي كه رنگ صورتم زرد است؟\r\nزن گفت: اي مرد تو حالت خوب است. بد گمان شده‌اي.\r\nاستاد گفت: تو هنوز لجاجت مي‌كني! اين رنج و بيماري مرا نمي‌بيني؟ اگر تو كور و كر شده‌اي من چه كنم؟ زن گفت : الآن آينه مي‌آورم تا در آينه ببيني، كه رنگت كاملاً عادي است. استاد فرياد زد و گفت: نه تو و نه آينه‌ات، هيچكدام راست نمي‌گوييد. تو هميشه با من كينه و دشمني داري. زود بستر خواب مرا آماده كن كه سرم سنگين شد، زن كمي ديرتر، بستر را آماده كرد، استاد فرياد زد و گفت تو دشمن مني. چرا ايستاده‌اي ؟ زن نمي‌دانست چه بگويد؟ با خود گفت اگر بگويم تو حالت خوب است و مريض نيستي، مرا به دشمني متهم مي‌كند و گمان بد مي‌برد كه من در هنگام نبودن او در خانه كار بد انجام مي‌دهم. اگر چيزي نگويم اين ماجرا جدي مي‌شود. زن بستر را آماده كرد و استاد روي تخت دراز كشيد. كودكان آنجا كنار استاد نشستند و آرام آرام درس مي‌خواندند و خود را غمگين نشان مي‌دادند. شاگرد زيرك با اشاره كرد كه بچه‌ها يواش يواش صداشان را بلند كردند. بعد گفت : آرام بخوانيد صداي شما استاد را آزار مي‌دهد. آيا ارزش دارد كه براي يك ديناري كه شما به استاد مي‌دهيد اينقدر درد سر بدهيد؟ استاد گفت: راست مي‌گويد. برويد. درد سرم را بيشتر كرديد. درس امروز تعطيل است. بچه‌ها براي سلامتي استاد دعا كردند و با شادي به سوي خانه‌ها رفتند. مادران با تعجب از بچه‌ها پرسيدند : چرا به مكتب نرفته‌ايد؟ كودكان گفتند كه از قضاي آسمان امروز استاد ما بيمار شد. مادران حرف شاگردان را باور نكردند و گفتند: شما دروغ مي‌گوييد. ما فردا به مكتب مي‌آييم تا اصل ماجرا را بدانيم. كودكان گفتند: بفرماييد، بروييد تا راست و دروغ حرف ما را بدانيد. بامداد فردا مادران به مكتب آمدند، استاد در بستر افتاده بود، از بس لحاف روي او بود عرق كرده بود و ناله مي‌كرد، مادران پرسيدند: چه شده؟ از كي درد سر داريد؟ ببخشيد ما خبر نداشتيم. استاد گفت: من هم بيخبر بودم، بچه‌‌ها مرا از اين درد پنهان باخبر كردند. من سرگرم كارم بودم و اين درد بزرگ در درون من پنهان بود. آدم وقتي با جديت به كار مشغول باشد رنج و بيماري خود را نمي‌فهمد.\r\n"},{"id":471,"category_id":5,"category_code":"s5","source_id":40,"title":"فيل در تاريكي","content":"شهري بود كه مردمش, اصلاً فيل نديده بودند, از هند فيلي آوردند و به خانة تاريكي بردند و مردم را به تماشاي آن دعوت كردند, مردم در آن تاريكي نمي‌توانستند فيل را با چشم ببينيد. ناچار بودند با دست آن را لمس كنند. كسي كه دستش به خرطوم فيل رسيد. گفت: فيل مانند يك لولة بزرگ است. ديگري كه گوش فيل را با دست گرفت؛ گفت: فيل مثل بادبزن است. يكي بر پاي فيل دست كشيد و گفت: فيل مثل ستون است. و كسي ديگر پشت فيل را با دست لمس كرد و فكر كرد كه فيل مانند تخت خواب است. آنها وقتي نام فيل را مي‌شنيدند هر كدام گمان مي‌كردند كه فيل همان است كه تصور كرده‌اند. فهم و تصور آنها از فيل مختلف بود و سخنانشان نيز متفاوت بود. اگر در آن خانه شمعي مي‌بود. اختلاف سخنان آنان از بين مي‌رفت. ادراك حسي مانند ادراك كف دست, ناقص و نارسا است. نمي‌توان همه چيز را با حس و عقل شناخت."},{"id":472,"category_id":5,"category_code":"s5","source_id":41,"title":"مارگير بغداد","content":"مارگيري در زمستان به كوهستان رفت تا مار بگيرد. در ميان برف اژدهاي بزرگ مرده‌اي ديد. خيلي ترسيد, امّا تصميم گرفت آن را به شهر بغداد بياورد تا مردم تعجب كنند, و بگويد كه اژدها را من با زحمت گرفته‌ام و خطر بزرگي را از سر راه مردم برداشته‌ام و پول از مردم بگيرد. او اژدها را كشان كشان , تا بغداد آورد. همه فكر مي‌كردند كه اژدها مرده است. اما اژدها زنده بود ولي در سرما يخ زده بود و مانند اژدهاي مرده بي‌حركت بود. دنيا هم مثل اژدها در ظاهر فسرده و بي‌جان است اما در باطن زنده و داراي روح است.\r\nمارگير به كنار رودخانة بغداد آمد تا اژدها را به نمايش بگذارد, مردم از هر طرف دور از جمع شدند, او منتظر بود تا جمعيت بيشتري بيايند و او بتواند پول بيشتري بگيرد. اژدها را زير فرش و پلاس پنهان كرده بود و براي احتياط آن را با طناب محكم بسته بود. هوا گرم شد و آفتابِ عراق, اژدها را گرم كرد يخهاي تن اژدها باز شد، اژدها تكان خورد، مردم ترسيدند، و فرار كردند، اژدها طنابها را پاره كرد و از زير پلاسها بيرون آمد, و به مردم حمله بُرد. مردم زيادي در هنگام فرار زير دست و پا كشته شدند. مارگير از ترس برجا خشك شد و از كار خود پشيمان گشت. ناگهان اژدها مارگير را يك لقمه كرد و خورد. آنگاه دور درخت پيچيد تا استخوانهاي مرد در شكم اژدها خُرد شود. شهوتِ ما مانند اژدهاست اگر فرصتي پيدا كند, زنده مي‌شود و ما را مي‌خورد.\r\n"},{"id":473,"category_id":5,"category_code":"s5","source_id":42,"title":"مرد لاف زن","content":"يك مرد لاف زن, پوست دنبه‌اي چرب در خانه داشت و هر روز لب و سبيل خود را چرب مي‌كرد و به مجلس ثروتمندان مي‌رفت و چنين وانمود مي‌كرد كه غذاي چرب خورده است. دست به سبيل خود مي‌كشيد. تا به حاضران بفهماند كه اين هم دليل راستي گفتار من. امّا شكمش از گرسنگي ناله مي‌كرد كه‌ اي درغگو, خدا , حيله و مكر تو را آشكار كند! اين لاف و دروغ تو ما را آتش مي‌زند. الهي, آن سبيل چرب تو كنده شود, اگر تو اين همه لافِ دروغ نمي‌زدي, لااقل يك نفر رحم مي‌كرد و چيزي به ما مي‌داد. اي مرد ابله لاف و خودنمايي روزي و نعمت را از آدم دور مي‌كند. شكم مرد, دشمن سبيل او شده بود و يكسره دعا مي‌كرد كه خدايا اين درغگو را رسوا كن تا بخشندگان بر ما رحم كنند, و چيزي به اين شكم و روده برسد. عاقبت دعاي شكم مستجاب شد و روزي گربه‌اي آمد و آن دنبة چرب را ربود. اهل خانه دنبال گربه دويدند ولي گربه دنبه را برد. پسر آن مرد از ترس اينكه پدر او را تنبيه كند رنگش پريد و به مجلس دويد, و با صداي بلند گفت پدر! پدر! گربه دنبه را برد. آن دنبه‌اي كه هر روز صبح لب و سبيلت را با آن چرب مي‌كردي. من نتوانستم آن را از گربه بگيرم. حاضران مجلس خنديدند, آنگاه بر آن مرد دلسوزي كردند و غذايش دادند. مرد ديد كه راستگويي سودمندتر است از لاف و دروغ."},{"id":474,"category_id":5,"category_code":"s5","source_id":43,"title":"شغال در خُمّ رنگ","content":"شغالي به درونِ خم رنگ‌آميزي رفت و بعد از ساعتي بيرون آمد, رنگش عوض شده بود. وقتي آفتاب به او مي‌تابيد رنگها مي‌درخشيد و رنگارنگ مي‌شد. سبز و سرخ و آبي و زرد و. .. شغال مغرور شد و گفت من طاووس بهشتي‌ام, پيش شغالان رفت. و مغرورانه ايستاد. شغالان پرسيدند, چه شده كه مغرور و شادكام هستي؟ غرورداري و از ما دوري مي‌كني؟ اين تكبّر و غرور براي چيست؟ يكي از شغالان گفت: اي شغالك آيا مكر و حيله‌اي در كار داري؟ يا واقعاً پاك و زيبا شده‌اي؟ آيا قصدِ فريب مردم را داري؟\r\nشغال گفت: در رنگهاي زيباي من نگاه كن, مانند گلستان صد رنگ و پرنشاط هستم. مرا ستايش كنيد. و گوش به فرمان من باشيد. من افتخار دنيا و اساس دين هستم. من نشانة لطف خدا هستم, زيبايي من تفسير عظمت خداوند است. ديگر به من شغال نگوييد. كدام شغال اينقدر زيبايي دارد. شغالان دور او جمع شدند او را ستايش كردند و گفتند اي والاي زيبا, تو را چه بناميم؟ گفت من طاووس نر هستم. شغالان گفتند: آيا صدايت مثل طاووس است؟ گفت: نه, نيست. گفتند: پس طاووس نيستي. دروغ مي‌گويي زيبايي و صداي طاووس هدية خدايي است. تو از ظاهر سازي و ادعا به بزرگي نمي‌رسي.\r\n"},{"id":475,"category_id":5,"category_code":"s5","source_id":44,"title":"نزاع چهار نفر بر سر انگور","content":"چهار نفر, با هم دوست بودند, عرب, ترك, رومي و ايراني, مردي به آنها يك دينار پول داد. ايراني گفت: «انگور» بخريم و بخوريم. عرب گفت: نه! من «عنب» مي‌خواهم, ترك گفت: بهتر است «اُزوُم» بخريم. رومي گفت: دعوا نكنيد! استافيل مي‌خريم, آنها به توافق نرسيدند. هر چند همة آنها يك ميوه، يعني انگور مي‌خواستند. از ناداني مشت بر هم مي‌زدند. زيرا راز و معناي نام‌ها را نمي‌دانستند. هر كدام به زبان خود انگور مي‌خواست. اگر يك مرد داناي زبان‌دان آنجا بود, آنها را آشتي مي‌داد و مي‌گفت من با اين يك دينار خواستة همه ي شما را مي‌خرم، يك دينار هر چهار خواستة شما را بر آورده مي‌كند. شما دل به من بسپاريد، خاموش باشيد. سخن شما موجب نزاع و دعوا است، چون معناي نام‌ها را مي‌دانم اختلاف شماها در نام است و در صورت, معنا و حقيقت يك چيز است."},{"id":476,"category_id":5,"category_code":"s5","source_id":45,"title":"درخت بي مرگي","content":"دانايي به رمز داستاني مي‌گفت: در هندوستان درختي است كه هر كس از ميوه‌اش بخورد پير نمي شود و نمي‌ميرد. پادشاه اين سخن را شنيد و عاشق آن ميوه شد, يكي از كاردانان دربار را به هندوستان فرستاد تا آن ميوه را پيدا كند و بياورد. آن فرستاده سال‌ها در هند جستجو كرد. شهر و جزيره‌اي نماند كه نرود. از مردم نشانيِ آن درخت را مي‌پرسيد, مسخره‌اش مي‌كردند. مي‌گفتند: ديوانه است. او را بازي مي‌گرفتند بعضي مي‌گفتند: تو آدم دانايي هستي در اين جست و جو رازي پنهان است. به او نشاني غلط مي‌دادند. از هر كسي چيزي مي‌شنيد. شاه براي او مال و پول مي‌فرستاد و او سال‌ها جست و جو كرد. پس از سختي‌هاي بسيار, نااميد به ايران برگشت, در راه مي‌گريست و نااميد مي‌رفت, تا در شهري به شيخ دانايي رسيد. پيش شيخ رفت و گريه كرد و كمك خواست. شيخ پرسيد: دنبال چه مي‌گردي؟ چرا نااميد شده‌اي؟\r\nفرستادة شاه گفت: شاهنشاه مرا انتخاب كرد تا درخت كم‌يابي را پيدا كنم كه ميوة آن آب حيات است و جاودانگي مي‌بخشد. سال‌ها جُستم و نيافتم. جز تمسخر و طنز مردم چيزي حاصل نشد. شيخ خنديد و گفت: اي مرد پاك دل! آن درخت, درخت علم است در دل انسان. درخت بلند و عجيب و گستردة دانش, آب حيات و جاودانگي است. تو اشتباه رفته‌اي، زيرا به دنبال صورت هستي نه معني, آن معناي بزرگ (علم) نام‌هاي بسيار دارد. گاه نامش درخت است و گاه آفتاب, گاه دريا و گاه ابر, علم صدها هزار آثار و نشان دارد. كمترين اثر آن عمر جاوادنه است.\r\nعلم و معرفت يك چيز است. يك فرد است. با نام‌ها و نشانه‌هاي بسيار. مانند پدرِ تو, كه نام‌هاي زياد دارد: براي تو پدر است, براي پدرش, پسر است, براي يكي دشمن است, براي يكي دوست است, صدها, اثر و نام دارد ولي يك شخص است. هر كه به نام و اثر نظر داشته باشد, مثل تو نااميد مي‌ماند, و هميشه در جدايي و پراكندگي خاطر و تفرقه است. تو نام درخت را گرفته‌اي نه راز درخت را. نام را رها كن به كيفيت و معني و صفات بنگر, تا به ذات حقيقت برسي, همة اختلاف‌ها و نزاع‌ها از نام آغاز مي‌شود. در درياي معني آرامش و اتحاد است.\r\n"},{"id":477,"category_id":5,"category_code":"s5","source_id":46,"title":"موشي كه مهار شتر را مي‌كشيد","content":"موشي, مهار شتري را به شوخي به دندان گرفت و به راه افتاد. شتر هم به شوخي به دنبال موش روان شد و با خود گفت: بگذار تا اين حيوانك لحظه‌اي خوش باشد, موش مهار را مي‌كشيد و شتر مي‌آمد. موش مغرور شد و با خود گفت: من پهلوانِ بزرگي هستم و شتر با اين عظمت را مي‌كشم. رفتند تا به كنار رودخانه‌اي رسيدند, پر آب, كه شير و گرگ از آن نمي‌توانستند عبور كنند. موش بر جاي خشك شد.\r\nشتر گفت: چرا ايستادي؟ چرا حيراني؟ مردانه پا در آب بگذار و برو, تو پيشواي من هستي, برو.\r\nموش گفت: آب زياد و خطرناك است. مي‌ترسم غرق شوم.\r\nشتر گفت: بگذار ببينم اندازة آب چقدر است؟ موش كنار رفت و شتر پايش را در آب گذاشت. آب فقط تا زانوي شتر بود. شتر به موش گفت: اي موش نادانِ كور چرا مي‌ترسي؟ آب تا زانو بيشتر نيست.\r\nموش گفت: آب براي تو مور است براي مثل اژدها. از زانو تا به زانو فرق‌ها بسيار است. آب اگر تا زانوي توست. صدها متر بالاتر از سرِ من است.\r\nشتر گفت: ديگر بي‌ادبي و گستاخي نكني. با دوستان هم قدّ خودت شوخي كن. موش با شتر هم سخن نيست. موش گفت: ديگر چنين كاري نمي‌كنم, توبه كردم. تو به خاطر خدا مرا ياري كن و از آب عبور ده, شتر مهرباني كرد و گفت بيا بر كوهان من بنشين تا هزار موش مثل تو را به راحتي از آب عبور دهم.\r\n"},{"id":478,"category_id":5,"category_code":"s5","source_id":47,"title":"پير و پزشك","content":"پيرمردي, پيش پزشك رفت و گفت: حافظه‌ام ضعيف شده است\r\nپزشك گفت: به علتِ پيري است\r\nپير: چشم‌هايم هم خوب نمي‌بيند\r\nپزشك: اي پير كُهن, علت آن پيري است\r\nپير: پشتم خيلي درد مي‌كند\r\nپزشك: اي پيرمرد لاغر اين هم از پيري است\r\nپير: هرچه مي‌خورم برايم خوب نيست\r\nطبيب گفت: ضعف معده هم از پيري است\r\nپير گفت: وقتي نفس مي‌كشم نفسم مي گيرد\r\nپزشك: تنگي نفس هم از پيري است وقتي فرا مي‌رسد صدها مرض مي‌آيد\r\nپيرمرد بيمار خشمگين شد و فرياد زد: اي احمق تو از علم طب همين جمله را آموختي؟! مگر عقل نداري و نمي‌داني كه خدا هر دردي را درماني داده است. تو خرِ احمق از بي‌عقلي در جا مانده‌اي. پزشك آرام گفت: اي پدر عمر تو از شصت بيشتر است. اين خشم و غضب تو هم از پيري است. همه اعضاي وجودت ضعيف شده صبر و حوصله‌ات ضعيف شده است. تو تحمل شنيدن دو جمله حرق حق را نداري. همة پيرها چنين هستند. به غير پيران حقيقت.\r\nاز برون پير است و در باطن صَبيّ خود چه چيز است؟ آن ولي و آن نبي\r\n"},{"id":479,"category_id":5,"category_code":"s5","source_id":48,"title":"مست و محتسب","content":"محتسب در نيمة شب, مستي را ديد كه كنار ديوار افتاده است. پيش رفت و گفت: تو مستي, بگو چه خورده‌اي؟ چه گناه و جُرمِ بزرگي كرده‌اي! چه خورده‌اي؟\r\nمست گفت: از چيزي كه در اين سبو بود خوردم.\r\nمحتسب: در سبو چه بود؟\r\nمست: چيزي كه من خوردم\r\nمحتسب: چه خورده‌اي؟\r\nمست: چيزي كه در اين سبو بود.\r\nاين پرسش و پاسخ مثل چرخ مي‌چرخيد و تكرار مي‌شد. محتسب گفت: «آه» كن تا دهانت را بو كنم. مست «هو» كرد. محتسب ناراحت شد و گفت: من مي‌گويم «آه» كن, تو «هو» مي‌كني؟ مست خنديد و گفت: «آه» نشانة غم است. امّا من شادم, غم ندارم, ميخوارانِ حقيقت از شادي «هو هو» مي‌زنند.\r\nمحتسب خشمگين شد, يقة مست را گرفت و گفت: تو جُرم كرده‌اي, بايد تو را به زندان ببرم. مست خنديد و گفت: من اگر مي‌توانستم برخيزم, به خانة خودم مي‌رفتم, چرا به زندان بيايم. من اگر عقل و هوش داشتم مثل مردان ديگر سركار و مغازه و دكان خود مي‌رفتم.\r\nمحتسب گفت: چيزي بده تا آزادت كنم. مست با خنده گفت: من برهنه‌ام , چيزي ندارم خود را زحمت مده.\r\n"},{"id":480,"category_id":5,"category_code":"s5","source_id":49,"title":"موسي و چوپان","content":"حضرت موسي در راهي چوپاني را ديد كه با خدا سخن مي‌گفت. چوپان مي‌گفت: اي خداي بزرگ تو كجا هستي, تا نوكرِ تو شوم, كفش‌هايت را تميز كنم, سرت را شانه كنم, لباس‌هايت را بشويم پشه‌هايت را بكشم. شير برايت بياورم. دستت را ببوسم, پايت را نوازش كنم. رختخوابت را تميز و آماده كنم. بگو كجايي؟ اي خُدا. همة بُزهاي من فداي تو باد.‌هاي و هوي من در كوه‌ها به ياد توست. چوپان فرياد مي‌زد و خدا را جستجو مي‌كرد.\r\nموسي پيش او رفت و با خشم گفت: اي مرد احمق, اين چگونه سخن گفتن است؟ با چه كسي مي‌گويي؟ موسي گفت: اي بيچاره, تو دين خود را از دست دادي, بي‌دين شدي. بي‌ادب شدي. اي چه حرفهاي بيهوده و غلط است كه مي‌گويي؟ خاموش باش, برو پنبه در دهانت كن تا خفه شوي, شايد خُدا تو را ببخشد. حرف‌هاي زشت تو جهان را آلوده كرد, تو دين و ايمان را پاره پاره كردي. اگر خاموش نشوي, آتش خشم خدا همة جهان را خواهد سوخت,\r\nچوپان از ترس, گريه كرد. گفت اي موسي تو دهان مرا دوختي, من پشيمانم, جان من سوخت. و بعد چوپان, لباسش را پاره كرد. فرياد كشيد و به بيابان فرار كرد.\r\nخداوند به موسي فرمود: اي پيامبر ما, چرا بندة ما را از ما دور كردي؟ ما ترا براي وصل كردن فرستاديم نه براي بريدن و جدا كردن. ما به هر كسي يك خلاق و روش جداگانه داده‌ايم. به هر كسي زبان و واژه‌هايي داده‌ايم. هر كس با زبانِ خود و به اندازة فهمِ خود با ما سخن مي‌گويد. هنديان زبان خاص خود دارند و ايرانيان زبان خاص خود و اعراب زباني ديگر. پادشاه زباني دارد و گدا و چوپان هر كدام زباني و روشي و مرامي مخصوصِ خود. ما به اختلاف زبانها و روش‌ها و صورت‌ها كاري نداريم كارِ ما با دل و درون است. اي موسي, آداب داني و صورت‌گري جداست و عاشقي و سوختگي جدا. ما با عشقان كار داريم. مذهب عاشقان از زبان و مذهب صورت پرستان جداست. مذهب عاشقان عشق است و در دين عشق لفظ و صورت مي‌سوزد و معنا مي‌ماند. صورت و زبان علت اختلاف است. ما لفظ و صورت نمي‌خواهيم ما سوز دل و پاكي مي‌خواهيم. موسي چون اين سخن‌ها را شنيد به بيابان رفت و دنبال چوپان دويد. ردپاي او را دنبال كرد. رد پاي ديگران فرق دارد. موسي چوپان را يافت او را گرفت و گفت: مژده مژده كه خداوند فرمود:\r\nهيچ ترتيبي و آدابي مجو هر چه مي‌خواهد دل تنگت, بگو\r\n"},{"id":481,"category_id":5,"category_code":"s5","source_id":50,"title":"تشنه بر سر ديوار","content":"در باغي چشمه‌اي‌بود و ديوارهاي بلند گرداگرد آن باغ, تشنه‌اي دردمند, بالاي ديوار با حسرت به آب نگاه مي‌كرد. ناگهان , خشتي از ديوار كند و در چشمه افكند. صداي آب, مثل صداي يار شيرين و زيبا به گوشش آمد, آب در نظرش, شراب بود. مرد آنقدر از صداي آب لذت مي‌برد كه تند تند خشت‌ها را مي‌كند و در آب مي‌افكند.\r\nآب فرياد زد: هاي, چرا خشت مي‌زني؟ از اين خشت زدن بر من چه فايده‌اي مي‌بري؟\r\nتشنه گفت: اي آب شيرين! در اين كار دو فايده است. اول اينكه شنيدن صداي آب براي تشنه مثل شنيدن صداي موسيقي رُباب است. نواي آن حيات بخش است, مرده را زنده مي‌كند. مثل صداي رعد و برق بهاري براي باغ سبزه و سنبل مي‌آورد. صداي آب مثل هديه براي فقير است. پيام آزادي براي زنداني است, بوي خداست كه از يمن به محمد رسيد , بوي يوسف لطيف و زيباست كه از پيراهنِ يوسف به پدرش يعقوب مي‌رسيد \r\nفايدة دوم اينكه: من هر خشتي كه بركنم به آب شيرين نزديكتر مي‌شوم, ديوار كوتاهتر مي‌شود. خم شدن و سجده در برابر خدا, مثل كندن خشت است. هر بار كه خشتي از غرور خود بكني, ديوار غرور تو كوتاهتر مي‌شود و به آب حيات و حقيقت نزديكتر مي‌شوي. هر كه تشنه‌تر باشد تندتر خشت‌ها را مي‌كند. هر كه آواز آب را عاشق‌تر باشد. خشت‌هاي بزرگتري برمي‌دارد.\r\n"},{"id":482,"category_id":5,"category_code":"s5","source_id":51,"title":"زنداني و هيزم فروش","content":"فقيري را به زندان بردند. او بسيار پرخُور بود و غذاي همة زندانيان را مي‌دزديد و مي‌خورد. زندانيان از او مي‌ترسيدند و رنج مي‌بردند, غذاي خود را پنهاني مي‌خوردند. روزي آنها به زندان‌بان گفتند: به قاضي بگو, اين مرد خيلي ما را آزار مي‌د‌هد. غذاي 10 نفر را مي‌خورد. گلوي او مثل تنور آتش است. سير نمي‌شود. همه از او مي‌ترسند. يا او را از زندان بيرون كنيد، يا غذا زيادتر بدهيد. قاضي پس از تحقيق و بررسي فهميد كه مرد پُرخور و فقير است. به او گفت: تو آزاد هستي, برو به خانه‌ات.\r\nزنداني گفت: اي قاضي, من كس و كاري ندارم, فقيرم, زندان براي من بهشت است. اگر از زندان بيرون بروم از گشنگي مي‌ميرم.\r\nقاضي گفت: چه شاهد و دليلي داري؟\r\nمرد گفت: همة مردم مي‌دانند كه من فقيرم. همه حاضران در دادگاه و زندانيان گواهي دادند كه او فقير است.\r\nقاضي گفت: او را دور شهر بگردانيد و فقرش را به همه اعلام كنيد. هيچ كس به او نسيه ندهد، وام ندهد، امانت ندهد. پس از اين هر كس از اين مرد شكايت كند. دادگاه نمي‌پذيرد\r\nآنگاه آن مرد فقير شكمو را بر شترِ يك مرد هيزم فروش سوار كردند, مردم هيزم فروش از صبح تا شب, فقير را كوچه به كوچه و محله به محله گرداند. در بازار و جلو حمام و مسجد فرياد مي‌زد: \"اي مردم! اين مرد را خوب بشناسيد, او فقير است. به او وام ندهيد! نسيه به او نفروشيد! با او دادوستد نكنيد, او دزد و پرخور و بي‌كس و كار است. خوب او را نگاه كنيد.\"\r\nشبانگاه, هيزم فروش, زنداني را از شتر پايين آورد و گفت: مزد من و كراية شترم را بده, من از صبح براي تو كار مي‌كنم. زنداني خنديد و گفت: تو نمي‌داني از صبح تا حالا چه مي‌گويي؟ به تمام مردم شهر گفتي و خودت نفهميدي؟ سنگ و كلوخ شهر مي‌دانند كه من فقيرم و تو نمي‌داني؟ دانش تو, عاريه است.\r\nنكته: طمع و غرض, بر گوش و هوش ما قفل مي‌زند. بسياري از دانشمندان يكسره از حقايق سخن مي‌گويند ولي خود نمي‌دانند مثل همين مرد هيزم فروش.\r\n"},{"id":483,"category_id":5,"category_code":"s5","source_id":52,"title":"خر برفت و خر برفت","content":"يك صوفي مسافر, در راه به خانقاهي رسيد و شب آنجا ماند. خرش را آب و علف داد و در طويله بست. و به جمع صوفيان رفت. صوفيان فقير و گرسنه بودند. آه از فقر كه كفر و بي‌ايمان به دنبال دارد. صوفيان, پنهاني خر مسافر را فروختند و غذا و خوردني خريدند و آن شب جشن مفّصلي بر پا كردند. مسافر خسته را احترام بسيار كردند و از آن خوردني‌ها خوردند. و صاحب خر را گرامي داشتند. او نيز بسيار لذّت مي‌برد. پس از غذا, رقص و سماع آغاز كردند. صوفيان همه اهل حقيقت نيستند.\r\nاز هزاران تن يكي تن صوفي‌اند باقيان در دولت او مي‌زيند\r\nرقص آغاز شد. مُطرب آهنگِ سنگيني آغاز كرد. و مي‌خواند: \" خر برفت و خر برفت و خر برفت.\"\r\nصوفيان با اين ترانه گرم شدند و تا صبح رقص و شادي كردند. دست افشاندند و پاي كوبيدند. مسافر نيز به تقليد از آنها ترانة خر برفت را با شور مي‌خواند. هنگام صبح همه خداحافظي كردند و رفتند صوفي بارش را برداشت و به طويله رفت تا بار بر پشت خر بگذارد و به راه ادامه دهد. اما خر در طويله نبود با خود گفت: حتماً خادم خانقاه خر را برده تا آب بدهد. خادم آمد ولي خر نبود, صوفي پرسيد: خر من كجاست. من خرم را به تو سپردم, و از تو مي‌خواهم.\r\nخادم گفت: صوفيان گرسنه حمله كردند, من از ترس جان تسليم شدم, آنها خر را بردند و فروختند تو گوشت لذيذ را ميان گربه‌ها رها كردي. صوفي گفت: چرا به من خبر ندادي, حالا آن‌ها همه رفته اند من از چه كسي شكايت كنم؟ خرم را خورده‌اند و رفته‌اند!\r\nخادم گفت: به خدا قسم, چند بار آمدم تو را خبر كنم. ديدم تو از همه شادتر هستي و بلندتر از همه مي‌خواندي خر برفت و خر برفت, خودت خبر داشتي و مي‌دانستي, من چه بگويم؟\r\nصوفي گفت: آن غذا لذيذ بود و آن ترانه خوش و زيبا, مرا هم خوش مي‌آمد.\r\nمر مرا تقليدشان بر باد داد اي دو صد لعنت بر آن تقليد باد\r\nآن صوفي از طمع و حرص به تقليد گرفتار شد و حرص عقل او را كور كرد.\r\n"},{"id":484,"category_id":5,"category_code":"s5","source_id":53,"title":"وحدت در عشق","content":"عاشقي به در خانة يارش رفت و در زد. معشوق گفت: كيست؟ عاشق گفت: «من» هستم. معشوق گفت: برو, هنوز زمان ورود خامان و ناپُختگان عشق به اين خانه نرسيده است. تو خام هستي.\r\n بايد مدتي در آتش جدايي بسوزي تا پخته شوي, هنوز آمادگي عشق را نداري. عاشق بيچاره برگشت و يكسال در آتش دوري و جدايي سوخت, پس از يك سال دوباره به در خانة معشوق آمد و با ترس و ادب در زد. مراقب بود تا سخن بي‌ادبانه‌اي از دهانش بيرون نيايد. با كمال ادب ايستاد. معشوق گفت: كيست در مي‌زند. عاشق گفت: اي دلبر دل رُبا, تو خودت هستي. تويي, تو. معشوق در باز كرد و گفت اكنون تو و من يكي شديم به درون خانه بيا. حالا يك «من» بيشتر نيست. دو «من»در خانة عشق جا نمي‌شود. مانند سر نخ كه اگر دو شاخه باشد در سوزن نمي‌رود.\r\nگفت اكنون چون مني اي من درآ نيست گنجايي دو من را در سرا\r\n"},{"id":485,"category_id":5,"category_code":"s5","source_id":54,"title":") روميان و چينيان (نقاشي و آينه","content":"نقاشان چيني با نقاشان رومي در حضور پادشاهي, از هنر و مهارت خود سخن مي‌گفتند و هر گروه ادعا داشتند كه در هنر نقاشي بر ديگري برتري دارند. شاه گفت: ما شما را امتحان مي‌كنيم تا ببينيم كدامشان, برتر و هنرمندتر هستيد.\r\nچينيان گفتند: ما يك ديوار اين خانه را پرده كشيدند و دو گروه نقاش , كار خود را آغاز كردند. چيني‌ها صد نوع رنگ از پادشاه خواستند و هر روز مواد و مصالح و رنگِ زيادي براي نقاشي به كار مي‌بردند.\r\nبعد از چند روز صداي ساز و دُهُل و شادي چيني‌ها بلند شد, آنها نقاشي خود را تمام كردند اما روميان هنوز از شاه رنگ و مصالح نگرفته بودند و از روز اول فقط ديوار را صيقل مي‌زدنند.\r\nچيني‌ها شاه را براي تماشاي نقاشي خود دعوت كردند. شاه نقاشي چيني‌ها را ديد و در شگفت شد. نقش‌ها از بس زيبا بود عقل را مي‌ربود. آنگاه روميان شاه را به تماشاي كار خود دعوت كردند. ديوار روميان مثلِ آينه صاف بود. ناگهان رومي‌ها پرده را كنار زدند عكس نقاشي چيني‌ها در آينة رومي‌ها افتاد و زيبايي آن چند برابر بود و چشم را خيره مي‌كرد شاه درمانده بود كه كدام نقاشي اصل است و كدام آينه است؟\r\nصوفيان مانند روميان هستند. درس و مشق و كتاب و تكرار درس ندارند, اما دل خود را از بدي و كينه و حسادت پاك كرده اند. سينة آنها مانند آينه است. همه نقشها را قبول مي‌كند و براي همه چيز جا دارد. دل آنها مثل آينه عميق و صاف است. هر چه تصوير و عكس در آن بريزد پُر نمي‌شود. آينه تا اَبد هر نقشي را نشان مي‌دهد. خوب و بد, زشت و زيبا را نشان مي‌دهد و اهلِ آينه از رنگ و بو و اندازه و حجم رهايي يافته اند. آنان صورت و پوستة علم و هنر را كنار گذاشته‌اند و به مغز و حقيقت جهان و اشياء دست يافته‌اند.\r\nهمة رنگ‌ها در نهايت به بي‌رنگي مي‌رسد. رنگ‌ها مانند ابر است و بي‌رنگي مانند نور مهتاب. رنگ و شكلي كه در ابر مي‌بيني, نور آفتاب و مهتاب است. نور بي‌رنگ است.\r\n"},{"id":486,"category_id":5,"category_code":"s5","source_id":55,"title":") روميان و چينيان (نقاشي و آينه","content":"نقاشان چيني با نقاشان رومي در حضور پادشاهي, از هنر و مهارت خود سخن مي‌گفتند و هر گروه ادعا داشتند كه در هنر نقاشي بر ديگري برتري دارند. شاه گفت: ما شما را امتحان مي‌كنيم تا ببينيم كدامشان, برتر و هنرمندتر هستيد.\r\nچينيان گفتند: ما يك ديوار اين خانه را پرده كشيدند و دو گروه نقاش , كار خود را آغاز كردند. چيني‌ها صد نوع رنگ از پادشاه خواستند و هر روز مواد و مصالح و رنگِ زيادي براي نقاشي به كار مي‌بردند.\r\nبعد از چند روز صداي ساز و دُهُل و شادي چيني‌ها بلند شد, آنها نقاشي خود را تمام كردند اما روميان هنوز از شاه رنگ و مصالح نگرفته بودند و از روز اول فقط ديوار را صيقل مي‌زدنند.\r\nچيني‌ها شاه را براي تماشاي نقاشي خود دعوت كردند. شاه نقاشي چيني‌ها را ديد و در شگفت شد. نقش‌ها از بس زيبا بود عقل را مي‌ربود. آنگاه روميان شاه را به تماشاي كار خود دعوت كردند. ديوار روميان مثلِ آينه صاف بود. ناگهان رومي‌ها پرده را كنار زدند عكس نقاشي چيني‌ها در آينة رومي‌ها افتاد و زيبايي آن چند برابر بود و چشم را خيره مي‌كرد شاه درمانده بود كه كدام نقاشي اصل است و كدام آينه است؟\r\nصوفيان مانند روميان هستند. درس و مشق و كتاب و تكرار درس ندارند, اما دل خود را از بدي و كينه و حسادت پاك كرده اند. سينة آنها مانند آينه است. همه نقشها را قبول مي‌كند و براي همه چيز جا دارد. دل آنها مثل آينه عميق و صاف است. هر چه تصوير و عكس در آن بريزد پُر نمي‌شود. آينه تا اَبد هر نقشي را نشان مي‌دهد. خوب و بد, زشت و زيبا را نشان مي‌دهد و اهلِ آينه از رنگ و بو و اندازه و حجم رهايي يافته اند. آنان صورت و پوستة علم و هنر را كنار گذاشته‌اند و به مغز و حقيقت جهان و اشياء دست يافته‌اند.\r\nهمة رنگ‌ها در نهايت به بي‌رنگي مي‌رسد. رنگ‌ها مانند ابر است و بي‌رنگي مانند نور مهتاب. رنگ و شكلي كه در ابر مي‌بيني, نور آفتاب و مهتاب است. نور بي‌رنگ است.\r\n"},{"id":487,"category_id":5,"category_code":"s5","source_id":56,"title":"خرس و اژدها","content":"اژدهايي خرسي را به چنگ آورده بود و مي‌خواست او را بكشد و بخورد. خرس فرياد مي‌كرد و كمك مي‌خواست, پهلواني رفت و خرس را از چنگِ اژدها نجات داد. خرس وقتي مهرباني آن پهلوان را ديد به پاي پهلوان افتاد و گفت من خدمتگزار تو مي‌شوم و هر جا بروي با تو مي‌آيم. آن دو با هم رفتند تا اينكه به جايي رسيدند, پهلوان خسته بود و مي‌خواست بخوابد. خرس گفت تو آسوده بخواب من نگهبان تو هستم مردي از آنجا مي‌گذشت و از پهلوان پرسيد اين خرس با تو چه مي‌كند؟\r\nپهلوان گفت: من او را نجات دادم و او دوست من شد.\r\nمرد گفت: به دوستي خرس دل مده, كه از هزار دشمن بدتر است.\r\nپهلوان گفت: اين مرد حسود است. خرس دوست من است من به او كمك كردم او به من خيانت نمي‌كند.\r\nمرد گفت: دوستي و محبت ابلهان, آدم را مي‌فريبد. او را رها كن زيرا خطرناك است.\r\nپهلوان گفت: اي مرد, مرا رها كن تو حسود هستي.\r\nمرد گفت: دل من مي‌گويد كه اين خرس به تو زيان بزرگي مي‌زند.\r\nپهلوان مرد را دور كرد و سخن او را گوش نكرد و مرد رفت. پهلوان خوابيد مگسي بر صورت او مي‌نشست و خرس مگس را مي‌زد. باز مگس مي‌نشست چند بار خرس مگس را زد اما مگس نمي‌رفت. \r\nخرس خشمناك شد و سنگ بزرگي از كوه برداشت و همينكه مگس روي صورت پهلوان نشست, خرس آن سنگ بزرگ را بر صورتِ پهلوان زد و سر مرد را خشخاش كرد. مهر آدم نادان مانند دوستي خرس است دشمني و دوستي او يكي است.\r\nدشمن دانا بلندت مي‌كند بر زمينت مي‌زند نادانِ دوست\r\n"},{"id":488,"category_id":5,"category_code":"s5","source_id":57,"title":"كشتي‌راني مگس","content":"مگسي بر پرِكاهي نشست كه آن پركاه بر ادرار خري روان بود. مگس مغرورانه بر ادرار خر كشتي مي‌راند و مي‌گفت: من علم دريانوردي و كشتي‌راني خوانده‌ام. در اين كار بسيار تفكر كرده‌ام. ببينيد اين دريا و اين كشتي را و مرا كه چگونه كشتي مي‌رانم. او در ذهن كوچك خود بر سر دريا كشتي مي‌راند آن ادرار، درياي بي‌ساحل به نظرش مي‌آمد و آن برگ كاه كشتي بزرگ, زيرا آگاهي و بينش او اندك بود. جهان هر كس به اندازة ذهن و بينش اوست. آدمِ مغرور و كج انديش مانند اين مگس است. و ذهنش به اندازه درك ادرار الاغ و برگ كاه."},{"id":489,"category_id":5,"category_code":"s5","source_id":58,"title":"شير بيسر و دم","content":"در شهر قزوين مردم عادت داشتند كه با سوزن بر پُشت و بازو و دست خود نقش‌هايي را رسم كنند, يا نامي بنويسند، يا شكل انسان و حيواني بكشند. كساني كه در اين كار مهارت داشتند «دلاك» ناميده مي‌شدند. دلاك , مركب را با سوزن در زير پوست بدن وارد مي‌كرد و تصويري مي‌كشيد كه هميشه روي تن مي‌ماند.\r\nروزي يك پهلوان قزويني پيش دلاك رفت و گفت بر شانه‌ام عكس يك شير را رسم كن. پهلوان روي زمين دراز كشيد و دلاك سوزن را برداشت و شروع به نقش زدن كرد. اولين سوزن را كه در شانة پهلوان فرو كرد. پهلوان از درد داد كشيد و گفت: آي! مرا كشتي. دلاك گفت: خودت خواسته‌اي, بايد تحمل كني, پهلوان پرسيد: چه تصويري نقش مي‌كني؟ دلاك گفت: تو خودت خواستي كه نقش شير رسم كنم. پهلوان گفت از كدام اندام شير آغاز كردي؟ دلاك گفت: از دُم شير. پهلوان گفت, نفسم از درد بند آمد. دُم لازم نيست. دلاك دوباره سوزن را فرو برد پهلوان فرياد زد, كدام اندام را مي‌كشي؟ دلاك گفت: اين گوش شير است. پهلوان گفت: اين شير گوش لازم ندارد. عضو ديگري را نقش بزن. باز دلاك سوزن در شانة پهلوان فرو كرد, پهلوان قزويني فغان برآورد و گفت: اين كدام عضو شير است؟ دلاك گفت: شكم شير است. پهلوان گفت: اين شير سير است. عكس شير هميشه سير است. شكم لازم ندارد.\r\nدلاك عصباني شد, و سوزن را بر زمين زد و گفت: در كجاي جهان كسي شير بي سر و دم و شكم ديده؟ خدا هرگز چنين شيري نيافريده است.\r\nشير بي دم و سر و اشكم كه ديد اين چنين شيري خدا خود نافريد.\r\n"},{"id":490,"category_id":5,"category_code":"s5","source_id":59,"title":"طوطي و بازرگان","content":"بازرگاني يك طوطي زيبا و شيرين سخن در قفس داشت. روزي كه آمادة سفرِ به هندوستان بود. از هر يك از خدمتكاران و كنيزان خود پرسيد كه چه ارمغاني برايتان بياورم, هر كدام از آنها چيزي سفارش دادند. بازرگان از طوطي پرسيد: چه سوغاتي از هند برايت بياورم؟ طوطي گفت: اگر در هند به طوطيان رسيدي حال و روز مرا براي آنها بگو. بگو كه من مشتاق ديدار شما هستم. ولي از بخت بد در قفس گرفتارم. بگو به شما سلام مي‌رساند و از شما كمك و راهنمايي مي‌خواهد.\r\n بگو آيا شايسته است من مشتاق شما باشم و در اين قفس تنگ از درد جدايي و تنهايي بميرم؟ وفاي دوستان كجاست؟ آيا رواست كه من در قفس باشم و شما در باغ و سبزه‌زار. اي ياران از اين مرغ دردمند و زار ياد كنيد. ياد ياران براي ياران خوب و زيباست. مرد بازرگان, پيام طوطي را شنيد و قول داد كه آن را به طوطيان هند برساند. وقتي به هند رسيد. چند طوطي را بر درختان جنگل ديد. \r\nاسب را نگهداشت و به طوطي‌ها سلام كرد و پيام طوطي خود را گفت: ناگهان يكي از طوطيان لرزيد و از درخت افتاد و در دم جان داد. بازرگان از گفتن پيام, پشيمان شد و گفت من باعث مرگ اين طوطي شدم, حتماً اين طوطي با طوطي من قوم و خويش بود. يا اينكه اين دو يك روح‌اند درد دو بدن. چرا گفتم و اين بيچاره را كشتم.\r\n زبان در دهان مثل سنگ و آهن است. سنگ و آهن را بيهوده بر هم مزن كه از دهان آتش بيرون مي‌پرد. جهان تاريك است مثل پنبه‌زار, چرا در پنبه‌زار آتش مي‌اندازي. كساني كه چشم مي‌بندند و جهاني را با سخنان خود آتش مي‌كشند ظالمند.\r\nعالَمي را يك سخن ويران كند// روبهان مرده را شيران كند\r\nبازرگان تجارت خود را با دردمندي تمام كرد و به شهر خود بازگشت, و براي هر يك از دوستان و خدمتكاران خود يك سوغات آورد. طوطي گفت: ارمغان من كو؟ آيا پيام مرا رساندي؟ طوطيان چه گفتند؟\r\nبازرگان گفت: من از آن پيام رساندن پشيمانم. ديگر چيزي نخواهم گفت. چرا من نادان چنان كاري كردم ديگر ندانسته سخن نخواهم گفت. طوطي گفت: چرا پيشمان شدي؟ چه اتفاقي افتاد؟ چرا ناراحتي؟ بازرگان چيزي نمي‌گفت. طوطي اسرار كرد. بازرگان گفت: وقتي پيام تو را به طوطيان گفتم, يكي از آنها از درد تو آگاه بود لرزيد و از درخت افتاد و مرد. من پشيمان شدم كه چرا گفتم؟\r\n امّا پشيماني سودي نداشت سخني كه از زبان بيرون جست مثل تيري است كه از كمان رها شده و برنمي‌گردد. طوطي چون سخن بازرگان را شنيد, لرزيد و افتاد و مُرد. بازرگان فرياد زد و كلاهش را بر زمين كوبيد, از ناراحتي لباس خود را پاره كرد, گفت: اي مرغ شيرين! زبان من چرا چنين شدي؟ اي دريغا مرغ خوش سخن من مُرد. اي زبان تو مايه زيان و بيچارگي من هستي.\r\nاي زبان هم آتـشي هم خرمني چند اين آتش در اين خرمن زني؟\r\nاي زبان هم گنج بي‌پايان تويي اي زبـان هم رنج بي‌درمان تويي\r\nبازرگان در غم طوطي ناله كرد, طوطي را از قفس در آورد و بيرون انداخت, ناگهان طوطي به پرواز درآمد و بر شاخ درخت بلندي نشست. بازرگان حيران ماند. و گفت: اي مرغ زيبا, مرا از رمز اين كار آگاه كن. آن طوطيِ هند به تو چه آموخت, كه چنين مرا بيچاره كرد.\r\n طوطي گفت: او به من با عمل خود پند داد و گفت ترا به خاطر شيرين زباني‌ات در قفس كرده‌اند , براي رهايي بايد ترك صفات كني. بايد فنا شوي. بايد هيچ شوي تا رها شوي. اگر دانه باشي مرغها ترا مي‌خورند. اگر غنچه باشي كودكان ترا مي‌چينند. هر كس زيبايي و هنر خود را نمايش دهد. صد حادثة بد در انتظار اوست. \r\nدوست و دشمن او را نظر مي‌زنند. دشمنان حسد و حيله مي‌ورزند. طوطي از بالاي درخت به بازرگان پند و اندرز داد و خداحافظي كرد. بازرگان گفت: برو! خدا نگه دار تو باشد. تو راه حقيقت را به من نشان دادي من هم به راه تو مي‌روم. جان من از طوطي كمتر نيست. براي رهايي جان بايد همه چيز را ترك كرد.\r\n"},{"id":491,"category_id":5,"category_code":"s5","source_id":60,"title":"طوطي و بقال","content":"يك فروشنده در دكان خود, يك طوطي سبز و زيبا داشت. طوطي, مثل آدم‌ها حرف مي‌زد و زبان انسان‌ها را بلد بود. نگهبان فروشگاه بود و با مشتري‌ها شوخي مي‌كرد و آنها را مي‌خنداند. و بازار فروشنده را گرم مي‌كرد.\r\nيك روز از يك فروشگاه به طرف ديگر پريد. بالش به شيشة روغن خورد. شيشه افتاد و نشكست و روغن‌ها ريخت. وقتي فروشنده آمد, ديد كه روغن‌ها ريخته و دكان چرب و كثيف شده است. فهميد كه كار طوطي است. چوب برداشت و بر سر طوطي زد. سر طوطي زخمي شد و موهايش ريخت و كَچَل شد. سرش طاس طاس شد.\r\nطوطي ديگر سخن نمي‌گفت و شيرين سخني نمي‌كرد. فروشنده و مشتري‌هايش ناراحت بودند. مرد فروشنده از كار خود پيشمان بود و مي‌گفت كاش دستم مي‌شكست تا طوطي را نمي‌زدم او دعا مي‌كرد تا طوطي دوباره سخن بگويد و بازار او را گرم كند.\r\nروزي فروشنده غمگين كنار دكان نشسته بود. يك مرد كچل طاس از خيابان مي‌گذشت سرش صاف صاف بود مثل پشت كاسة مسي.\r\nناگهان طوطي گفت: اي مرد كچل , چرا شيشة روغن را شكستي و كچل شدي؟\r\nتو با اين كار به انجمن كچل‌ها آمدي و عضو انجمن ما شدي؟ نبايد روغن‌ها را مي‌ريختي. مردم از مقايسة طوطي خنديدند. او فكر مي‌كرد هر كه كچل باشد. روغن ريخته است.\r\n"},{"id":492,"category_id":5,"category_code":"s5","source_id":61,"title":"پادشاه و كنيزك","content":"پادشاه قدرتمند و توانايي, روزي براي شكار با درباريان خود به صحرا رفت, در راه كنيزك زيبايي ديد و عاشق او شد. پول فراوان داد و دخترك را از اربابش خريد, پس از مدتي كه با كنيزك بود. كنيزك بيمار شد و شاه بسيار غمناك گرديد. از سراسر كشور, پزشكان ماهر را براي درمان او به دربار فرا خواند, و گفت: جان من به جان اين كنيزك وابسته است, اگر او درمان نشود, من هم خواهم مرد.\r\n هر كس جانان مرا درمان كند, طلا و مرواريد فراوان به او مي‌دهم. پزشكان گفتند: ما جانبازي مي‌كنيم و با همفكري و مشاوره او را حتماً درمان مي‌كنيم. هر يك از ما يك مسيح شفادهنده است. پزشكان به دانش خود مغرور بودند و يادي از خدا نكردند. خدا هم عجز و ناتواني آنها را به ايشان نشان داد. پزشكان هر چه كردند, فايده نداشت. دخترك از شدت بيماري مثل موي, باريك و لاغر شده بود. شاه يكسره گريه مي‌كرد. داروها, جواب معكوس مي‌داد. شاه از پزشكان نااميد شد. و پابرهنه به مسجد رفت و در محرابِ مسجد به گريه نشست. آنقدر گريه كرد كه از هوش رفت. وقتي به هوش آمد, دعا كرد. گفت اي خداي بخشنده, من چه بگويم, تو اسرار درون مرا به روشني مي‌داني. اي خدايي كه هميشه پشتيبان ما بوده‌اي, بارِ ديگر ما اشتباه كرديم. شاه از جان و دل دعا كرد, ناگهان درياي بخشش و لطف خداوند جوشيد, شاه در ميان گريه به خواب رفت. در خواب ديد كه يك پيرمرد زيبا و نوراني به او مي‌گويد: اي شاه مُژده بده كه خداوند دعايت را قبول كرد, فردا مرد ناشناسي به دربار مي‌آيد. او پزشك دانايي است. درمان هر دردي را مي‌داند, صادق است و قدرت خدا در روح اوست. منتظر او باش.\r\nفردا صبح هنگام طلوع خورشيد, شاه بر بالاي قصر خود منتظر نشسته بود, ناگهان مرد داناي خوش سيما از دور پيدا شد, او مثل آفتاب در سايه بود, مثل ماه مي‌درخشيد. بود و نبود. مانند خيال, و رؤيا بود. آن صورتي كه شاه در رؤياي مسجد ديده بود در چهرة اين مهمان بود. شاه به استقبال رفت. اگر چه آن مرد غيبي را نديده بود اما بسيار آشنا به نظر مي‌آمد. گويي سالها با هم آشنا بوده‌اند. و جانشان يكي بوده است.\r\nشاه از شادي, در پوست نمي‌گنجيد. گفت اي مرد: محبوب حقيقي من تو بوده‌اي نه كنيزك. كنيزك, ابزار رسيدن من به تو بوده است. آنگاه مهمان را بوسيد و دستش را گرفت و با احترام بسيار به بالاي قصر برد.\r\n پس از صرف غذا و رفع خستگي راه, شاه پزشك را پيش كنيزك برد و قصة بيماري او را گفت: حكيم، دخترك را معاينه كرد. و آزمايش‌هاي لازم را انجام داد. و گفت: همة داروهاي آن پزشكان بيفايده بوده و حال مريض را بدتر كرده, آنها از حالِ دختر بي‌خبر بودند و معالجة تن مي‌كردند. حكيم بيماري دخترك را كشف كرد, امّا به شاه نگفت. او فهميد دختر بيمار دل است. تنش خوش است و گرفتار دل است. عاشق است.\r\nعاشقي پيداست از زاري دل نيست بيماري چو بيماري دل\r\nدرد عاشق با ديگر دردها فرق دارد. عشق آينة اسرارِ خداست. \r\nعقل از شرح عشق ناتوان است. شرحِ عشق و عاشقي را فقط خدا مي‌داند. حكيم به شاه گفت: خانه را خلوت كن! همه بروند بيرون، حتي خود شاه. من مي‌خواهم از اين دخترك چيزهايي بپرسم. همه رفتند، حكيم ماند و دخترك. حكيم آرام آرام از دخترك پرسيد: شهر تو كجاست؟ دوستان و خويشان تو كي هستند؟ پزشك نبض دختر را گرفته بود و مي‌پرسيد و دختر جواب مي‌داد. از شهرها و مردمان مختلف پرسيد، از بزرگان شهرها پرسيد، نبض آرام بود، تا به شهر سمرقند رسيد، ناگهان نبض دختر تند شد و صورتش سرخ شد. \r\nحكيم از محله‌هاي شهر سمر قند پرسيد. نام كوچة غاتْفَر، نبض را شديدتر كرد. حكيم فهميد كه دخترك با اين كوچه دلبستگي خاصي دارد. پرسيد و پرسيد تا به نام جوان زرگر در آن كوچه رسيد، رنگ دختر زرد شد، حكيم گفت: بيماريت را شناختم، بزودي تو را درمان مي‌كنم. اين راز را با كسي نگويي. راز مانند دانه است اگر راز را در دل حفظ كني مانند دانه از خاك مي‌رويد و سبزه و درخت مي‌شود. حكيم پيش شاه آمد و شاه را از كار دختر آگاه كرد و گفت: چارة درد دختر آن است كه جوان زرگر را از سمرقند به اينجا بياوري و با زر و پول و او را فريب دهي تا دختر از ديدن او بهتر شود. \r\nشاه دو نفر داناي كار دان را به دنبال زرگر فرستاد. آن دو زرگر را يافتند او را ستودند و گفتند كه شهرت و استادي تو در همه جا پخش شده، شاهنشاه ما تو را براي زرگري و خزانه داري انتخاب كرده است. اين هديه‌ها و طلاها را برايت فرستاده و از تو دعوت كرده تا به دربار بيايي، در آنجا بيش از اين خواهي ديد.\r\n زرگر جوان، گول مال و زر را خورد و شهر و خانواده‌اش را رها كرد و شادمان به راه افتاد. او نمي‌دانست كه شاه مي‌خواهد او را بكشد. سوار اسب تيزپاي عربي شد و به سمت دربار به راه افتاد. آن هديه‌ها خون بهاي او بود. در تمام راه خيال مال و زر در سر داشت. وقتي به دربار رسيدند حكيم او را به گرمي استقبال كرد و پيش شاه برد، شاه او را گرامي داشت و خزانه‌هاي طلا را به او سپرد و او را سرپرست خزانه كرد. حكيم گفت: اي شاه اكنون بايد كنيزك را به اين جوان بدهي تا بيماريش خوب شود. به دستور شاه كنيزك با جوان زرگر ازدواج كردند و شش ماه در خوبي و خوشي گذراندند تا حال دخترك خوبِ خوب شد. آنگاه حكيم دارويي ساخت و به زرگر داد. جوان روز بروز ضعيف مي‌شد. پس از يكماه زشت و مريض و زرد شد و زيبايي و شادابي او از بين رفت و عشق او در دل دخترك سرد شد:\r\nعشقهايي كز پي رنگي بود\r\nعشق نبود عاقبت ننگي بود\r\nزرگر جوان از دو چشم خون مي‌گريست. روي زيبا دشمن جانش بود مانند طاووس كه پرهاي زيبايش دشمن اويند. زرگر ناليد و گفت: من مانند آن آهويي هستم كه صياد براي نافة خوشبو خون او را مي‌ريزد. من مانند روباهي هستم كه به خاطر پوست زيبايش او را مي‌كشند. من آن فيل هستم كه براي استخوان عاج زيبايش خونش را مي‌ريزند. \r\nاي شاه مرا كشتي. اما بدان كه اين جهان مانند كوه است و كارهاي ما مانند صدا در كوه مي‌پيچد و صداي اعمال ما دوباره به ما برمي‌گردد. زرگر آنگاه لب فروبست و جان داد. كنيزك از عشق او خلاص شد. عشق او عشق صورت بود. عشق بر چيزهاي ناپايدار. پايدار نيست. عشق زنده, پايدار است. عشق به معشوق حقيقي كه پايدار است. هر لحظه چشم و جان را تازه تازه‌تر مي‌كند مثل غنچه.\r\nعشق حقيقي را انتخاب كن, كه هميشه باقي است. جان ترا تازه مي‌كند. عشق كسي را انتخاب كن كه همة پيامبران و بزرگان از عشقِ او به والايي و بزرگي يافتند. و مگو كه ما را به درگاه حقيقت راه نيست در نزد كريمان و بخشندگان بزرگ كارها دشوار نيست.\r\n"}];
